import { useEffect, useState } from 'react'
import { useBoard } from './state/useBoard.js'
import { useTheme } from './state/useTheme.js'
import { isEditableTarget } from './utils/dom.js'
import Board from './components/Board.jsx'
import Toolbar from './components/Toolbar.jsx'

export default function App() {
  const { board, addCard, duplicateCards, updateCard, moveCard, removeCards, resetBoard } = useBoard()
  const { theme, toggleTheme } = useTheme()
  const [selectedIds, setSelectedIds] = useState(() => new Set())

  useEffect(() => {
    function onKeyDown(e) {
      if (selectedIds.size === 0) return
      const mod = e.metaKey || e.ctrlKey

      if (mod && e.key.toLowerCase() === 'd') {
        e.preventDefault()
        const newIds = duplicateCards([...selectedIds])
        if (newIds.length) setSelectedIds(new Set(newIds))
        return
      }

      if (!mod && (e.key === 'Backspace' || e.key === 'Delete') && !isEditableTarget(e.target)) {
        e.preventDefault()
        removeCards([...selectedIds])
        setSelectedIds(new Set())
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [duplicateCards, removeCards, selectedIds])

  function handleCreateCard(x, y) {
    setSelectedIds(new Set([addCard({ x, y })]))
  }

  return (
    <div className="app">
      <Toolbar onReset={resetBoard} theme={theme} onToggleTheme={toggleTheme} />
      <Board
        board={board}
        selectedIds={selectedIds}
        onSelectionChange={setSelectedIds}
        onCreateCard={handleCreateCard}
        actions={{ updateCard, moveCard }}
      />
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import Card from './Card.jsx'
import { COLORS, GRID_SIZE } from '../data/board.js'
import { isEditableTarget } from '../utils/dom.js'

const MIN_ZOOM = 0.25
const MAX_ZOOM = 2.5
const ZOOM_BUTTON_STEP = 1.2
const WHEEL_ZOOM_INTENSITY = 0.0015
const MARQUEE_DRAG_THRESHOLD = 3

const SHORTCUTS = [
  ['Double-click canvas', 'Create a new note'],
  ['Drag on canvas', 'Select multiple notes'],
  ['Shift + click / drag', 'Add to selection'],
  ['Drag a note', 'Move selected note(s)'],
  ['Right-click + drag', 'Pan the canvas'],
  ['Scroll', 'Zoom in / out'],
  ['z', 'Reset zoom to 100% (nothing selected)'],
  ['⌘/Ctrl + D', 'Duplicate selected note(s)'],
  ['Backspace / Delete', 'Delete selected note(s)'],
]

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value))
}

export default function Board({ board, selectedIds, onSelectionChange, onCreateCard, actions }) {
  const boardElRef = useRef(null)
  const panRef = useRef(null)
  const marqueeRef = useRef(null)
  const cardElsRef = useRef(new Map())
  const [view, setView] = useState({ x: 0, y: 0, zoom: 1 })
  const [panning, setPanning] = useState(false)
  const [marqueeRect, setMarqueeRect] = useState(null)
  const [helpOpen, setHelpOpen] = useState(false)

  // Read synchronously by the global 'z' listener below, so that listener
  // can be registered exactly once and never needs to be re-created.
  const selectedIdsRef = useRef(selectedIds)
  selectedIdsRef.current = selectedIds

  useEffect(() => {
    const el = boardElRef.current
    if (!el) return

    function onWheel(e) {
      e.preventDefault()
      const rect = el.getBoundingClientRect()
      zoomAt(e.clientX - rect.left, e.clientY - rect.top, Math.exp(-e.deltaY * WHEEL_ZOOM_INTENSITY))
    }

    el.addEventListener('wheel', onWheel, { passive: false })
    return () => el.removeEventListener('wheel', onWheel)
  }, [])

  // Registered exactly once for the life of the component — reads the
  // latest selection via selectedIdsRef, so there's nothing here that can
  // ever go stale or need re-subscribing.
  useEffect(() => {
    function onKeyDown(e) {
      if (e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return
      // Check the physical key rather than e.key — Caps Lock alone flips
      // e.key to 'Z' without setting shiftKey, which would otherwise block
      // a plain, un-shifted press of the key.
      if (e.code !== 'KeyZ') return
      if (selectedIdsRef.current.size > 0) return
      if (isEditableTarget(e.target)) return
      e.preventDefault()
      resetZoom()
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  useEffect(() => {
    if (!helpOpen) return
    function onKeyDown(e) {
      if (e.key === 'Escape') setHelpOpen(false)
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [helpOpen])

  // Keep (anchorX, anchorY) — in board-viewport pixels — visually fixed while
  // zoom changes by `factor`, so wheel-zoom tracks the cursor and button-zoom
  // tracks the viewport center.
  function zoomAt(anchorX, anchorY, factor) {
    setView((v) => {
      const newZoom = clamp(v.zoom * factor, MIN_ZOOM, MAX_ZOOM)
      if (newZoom === v.zoom) return v
      const worldX = (anchorX - v.x) / v.zoom
      const worldY = (anchorY - v.y) / v.zoom
      return { zoom: newZoom, x: anchorX - worldX * newZoom, y: anchorY - worldY * newZoom }
    })
  }

  function zoomByButton(factor) {
    const rect = boardElRef.current.getBoundingClientRect()
    zoomAt(rect.width / 2, rect.height / 2, factor)
  }

  // Reads the current zoom from the setState updater rather than the
  // outer `view` closure, so it's correct even when called from a
  // long-lived event listener that isn't re-created on every zoom/pan tick.
  function resetZoom() {
    const rect = boardElRef.current.getBoundingClientRect()
    const anchorX = rect.width / 2
    const anchorY = rect.height / 2
    setView((v) => {
      if (v.zoom === 1) return v
      const worldX = (anchorX - v.x) / v.zoom
      const worldY = (anchorY - v.y) / v.zoom
      return { zoom: 1, x: anchorX - worldX, y: anchorY - worldY }
    })
  }

  function getSiblingRects(excludeIds) {
    const excludeSet = excludeIds instanceof Set ? excludeIds : new Set(excludeIds)
    const rects = []
    cardElsRef.current.forEach((el, id) => {
      if (excludeSet.has(id)) return
      rects.push({ x: el.offsetLeft, y: el.offsetTop, width: el.offsetWidth, height: el.offsetHeight })
    })
    return rects
  }

  // When dragging a card that's part of a multi-selection, every other
  // selected card should ride along, keeping the group's relative layout.
  function getGroupOrigins(id) {
    if (!selectedIds.has(id) || selectedIds.size <= 1) return []
    return board.cards
      .filter((c) => c.id !== id && selectedIds.has(c.id))
      .map((c) => ({ id: c.id, x: c.x, y: c.y }))
  }

  function handleCardSelect(id, additive) {
    onSelectionChange((prev) => {
      if (additive) {
        const next = new Set(prev)
        if (next.has(id)) next.delete(id)
        else next.add(id)
        return next
      }
      // Clicking (without dragging) a card that's already part of a
      // multi-selection keeps the group intact, so it can be dragged as one.
      if (prev.has(id) && prev.size > 1) return prev
      return new Set([id])
    })
  }

  function handlePointerDown(e) {
    if (helpOpen) {
      // Clicking anywhere outside the panel (the backdrop) just dismisses
      // it — don't also treat that click as a canvas interaction.
      if (!e.target.closest('.board__help') && !e.target.closest('.help-panel')) {
        setHelpOpen(false)
      }
      return
    }
    if (e.button === 2) {
      e.preventDefault()
      panRef.current = { startX: e.clientX, startY: e.clientY, originX: view.x, originY: view.y }
      setPanning(true)
      e.currentTarget.setPointerCapture(e.pointerId)
      return
    }
    if (e.button !== 0) return
    if (
      e.target.closest('.card') ||
      e.target.closest('.card-color-menu') ||
      e.target.closest('.board__zoom') ||
      e.target.closest('.board__help')
    ) {
      return
    }
    const rect = boardElRef.current.getBoundingClientRect()
    marqueeRef.current = {
      startScreenX: e.clientX - rect.left,
      startScreenY: e.clientY - rect.top,
      baseSelection: e.shiftKey ? new Set(selectedIds) : new Set(),
      moved: false,
    }
    e.currentTarget.setPointerCapture(e.pointerId)
  }

  function handlePointerMove(e) {
    if (marqueeRef.current) {
      const rect = boardElRef.current.getBoundingClientRect()
      const curScreenX = e.clientX - rect.left
      const curScreenY = e.clientY - rect.top
      const { startScreenX, startScreenY, baseSelection } = marqueeRef.current

      const x = Math.min(startScreenX, curScreenX)
      const y = Math.min(startScreenY, curScreenY)
      const w = Math.abs(curScreenX - startScreenX)
      const h = Math.abs(curScreenY - startScreenY)
      if (w > MARQUEE_DRAG_THRESHOLD || h > MARQUEE_DRAG_THRESHOLD) marqueeRef.current.moved = true
      setMarqueeRect({ x, y, w, h })

      const worldX1 = (x - view.x) / view.zoom
      const worldY1 = (y - view.y) / view.zoom
      const worldX2 = (x + w - view.x) / view.zoom
      const worldY2 = (y + h - view.y) / view.zoom

      const hits = new Set(baseSelection)
      cardElsRef.current.forEach((el, id) => {
        const left = el.offsetLeft
        const top = el.offsetTop
        const overlaps =
          left < worldX2 && left + el.offsetWidth > worldX1 && top < worldY2 && top + el.offsetHeight > worldY1
        if (overlaps) hits.add(id)
      })
      onSelectionChange(hits)
      return
    }

    if (!panRef.current) return
    const { startX, startY, originX, originY } = panRef.current
    const x = originX + (e.clientX - startX)
    const y = originY + (e.clientY - startY)
    setView((v) => ({ ...v, x, y }))
  }

  function handlePointerUp(e) {
    if (marqueeRef.current) {
      const wasDrag = marqueeRef.current.moved
      marqueeRef.current = null
      setMarqueeRect(null)
      if (!wasDrag) onSelectionChange(new Set())
      try {
        e.currentTarget.releasePointerCapture(e.pointerId)
      } catch {
        // ignore
      }
      return
    }

    if (!panRef.current) return
    panRef.current = null
    setPanning(false)
    try {
      e.currentTarget.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  function handleDoubleClick(e) {
    if (
      e.target.closest('.card') ||
      e.target.closest('.board__zoom') ||
      e.target.closest('.card-color-menu') ||
      e.target.closest('.board__help')
    ) {
      return
    }
    const rect = boardElRef.current.getBoundingClientRect()
    const worldX = (e.clientX - rect.left - view.x) / view.zoom
    const worldY = (e.clientY - rect.top - view.y) / view.zoom
    onCreateCard?.(worldX, worldY)
  }

  // Anchor the shared color menu to the bounding box of every selected card.
  let colorMenuAnchor = null
  if (selectedIds.size > 0) {
    let left = Infinity
    let top = Infinity
    let right = -Infinity
    selectedIds.forEach((id) => {
      const el = cardElsRef.current.get(id)
      if (!el) return
      left = Math.min(left, el.offsetLeft)
      top = Math.min(top, el.offsetTop)
      right = Math.max(right, el.offsetLeft + el.offsetWidth)
    })
    if (Number.isFinite(left)) colorMenuAnchor = { left: right + GRID_SIZE, top }
  }

  const selectedColors = new Set(board.cards.filter((c) => selectedIds.has(c.id)).map((c) => c.color))
  const commonColor = selectedColors.size === 1 ? [...selectedColors][0] : null

  function handleColorPick(name) {
    selectedIds.forEach((id) => actions.updateCard(id, { color: name }))
  }

  return (
    <div
      ref={boardElRef}
      className={`board${panning ? ' board--panning' : ''}`}
      style={{
        backgroundPosition: `${view.x}px ${view.y}px`,
        backgroundSize: `${GRID_SIZE * view.zoom}px ${GRID_SIZE * view.zoom}px`,
      }}
      onContextMenu={(e) => e.preventDefault()}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onDoubleClick={handleDoubleClick}
    >
      <div
        className="board__layer"
        style={{ transform: `translate(${view.x}px, ${view.y}px) scale(${view.zoom})` }}
      >
        {board.cards.map((card) => (
          <Card
            key={card.id}
            card={card}
            zoom={view.zoom}
            selected={selectedIds.has(card.id)}
            onSelect={(additive) => handleCardSelect(card.id, additive)}
            onMove={actions.moveCard}
            onUpdate={actions.updateCard}
            getSiblingRects={getSiblingRects}
            getGroupOrigins={getGroupOrigins}
            registerRef={(el) => {
              if (el) cardElsRef.current.set(card.id, el)
              else cardElsRef.current.delete(card.id)
            }}
          />
        ))}

        {colorMenuAnchor && (
          <div className="card-color-menu" style={{ left: colorMenuAnchor.left, top: colorMenuAnchor.top }}>
            {Object.entries(COLORS).map(([name, hex]) => (
              <button
                key={name}
                className={`swatch${commonColor === name ? ' swatch--active' : ''}`}
                style={{ background: hex }}
                title={name}
                onClick={() => handleColorPick(name)}
              />
            ))}
          </div>
        )}
      </div>

      {marqueeRect && (
        <div
          className="board__marquee"
          style={{ left: marqueeRect.x, top: marqueeRect.y, width: marqueeRect.w, height: marqueeRect.h }}
        />
      )}

      <button
        className="board__zoom-btn board__help"
        onClick={() => setHelpOpen((v) => !v)}
        title="Keyboard shortcuts"
      >
        ?
      </button>

      {helpOpen && (
        <div className="help-backdrop">
          <div className="help-panel">
            <h2 className="help-panel__title">Keyboard shortcuts</h2>
            <table className="help-panel__table">
              <tbody>
                {SHORTCUTS.map(([key, desc]) => (
                  <tr key={key}>
                    <td className="help-panel__key">{key}</td>
                    <td>{desc}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <div className="board__zoom">
        <button className="board__zoom-btn" onClick={() => zoomByButton(1 / ZOOM_BUTTON_STEP)} title="Zoom out">
          −
        </button>
        <button className="board__zoom-btn board__zoom-btn--reset" onClick={resetZoom} title="Reset zoom">
          {Math.round(view.zoom * 100)}%
        </button>
        <button className="board__zoom-btn" onClick={() => zoomByButton(ZOOM_BUTTON_STEP)} title="Zoom in">
          +
        </button>
      </div>
    </div>
  )
}

