function resetZoom() {
  const rect = boardElRef.current.getBoundingClientRect()
  const anchorX = rect.width / 2
  const anchorY = rect.height / 2
  setView((v) => {
    if (v.zoom === 1) return v
    const worldX = (anchorX - v.x) / v.zoom
    const worldY = (anchorY - v.y) / v.zoom
    return { zoom: 1, x: anchorX - worldX, y: anchorY - worldY }
  })
}

// Shift+Z toggles: first press pins zoom at 100% (remembering the prior
// view), a second press resumes exactly where the user left off.
function toggleZoom() {
  setView((v) => {
    if (v.zoom !== 1) {
      savedViewRef.current = v
      const rect = boardElRef.current.getBoundingClientRect()
      const anchorX = rect.width / 2
      const anchorY = rect.height / 2
      const worldX = (anchorX - v.x) / v.zoom
      const worldY = (anchorY - v.y) / v.zoom
      return { zoom: 1, x: anchorX - worldX, y: anchorY - worldY }
    }
    if (savedViewRef.current) {
      const saved = savedViewRef.current
      savedViewRef.current = null
      return saved
    }
    return v
  })
}

