const [helpOpen, setHelpOpen] = useState(false)

// Read synchronously by the global 'z' listener below, so that listener
// can be registered exactly once and never needs to be re-created.
const selectedIdsRef = useRef(selectedIds)
selectedIdsRef.current = selectedIds

// Holds the pre-reset view while zoom is pinned at 100% via Shift+Z, so a
// second press can resume exactly where the user left off.
const savedViewRef = useRef(null)

useEffect(() => {
  const el = boardElRef.current
  if (!el) return

  function onWheel(e) {
    e.preventDefault()
    const rect = el.getBoundingClientRect()
    zoomAt(e.clientX - rect.left, e.clientY - rect.top, Math.exp(-e.deltaY * WHEEL_ZOOM_INTENSITY))
  }

  el.addEventListener('wheel', onWheel, { passive: false })
  return () => el.removeEventListener('wheel', onWheel)
}, [])

// Registered exactly once for the life of the component — reads the
// latest selection via selectedIdsRef, so there's nothing here that can
// ever go stale or need re-subscribing.
useEffect(() => {
  function onKeyDown(e) {
    if (e.metaKey || e.ctrlKey || e.altKey || !e.shiftKey) return
    // Check the physical key rather than e.key — Caps Lock flips e.key in
    // ways that vary by platform, so match the key position instead.
    if (e.code !== 'KeyZ') return
    if (selectedIdsRef.current.size > 0) return
    if (isEditableTarget(e.target)) return
    e.preventDefault()
    toggleZoom()
  }

  window.addEventListener('keydown', onKeyDown)
  return () => window.removeEventListener('keydown', onKeyDown)
}, [])

useEffect(() => {
  if (!helpOpen) return
  function onKeyDown(e) {
    if (e.key === 'Escape') setHelpOpen(false)
  }
  window.addEventListener('keydown', onKeyDown)
  return () => window.removeEventListener('keydown', onKeyDown)
}, [helpOpen])

// Keep (anchorX, anchorY) — in board-viewport pixels — visually fixed while
// zoom changes by `factor`, so wheel-zoom tracks the cursor and button-zoom
// tracks the viewport center.
function zoomAt(anchorX, anchorY, factor) {
  setView((v) => {
    const newZoom = clamp(v.zoom * factor, MIN_ZOOM, MAX_ZOOM)
    if (newZoom === v.zoom) return v
    const worldX = (anchorX - v.x) / v.zoom
    const worldY = (anchorY - v.y) / v.zoom
    return { zoom: newZoom, x: anchorX - worldX * newZoom, y: anchorY - worldY * newZoom }
  })
}

function zoomByButton(factor) {
  const rect = boardElRef.current.getBoundingClientRect()
  zoomAt(rect.width / 2, rect.height / 2, factor)
}

// Reads the current zoom from the setState updater rather than the
// outer `view` closure, so it's correct even when called from a
// long-lived event listener that isn't re-created on every zoom/pan tick.
function resetZoom() {
  const rect = boardElRef.current.getBoundingClientRect()
  const anchorX = rect.width / 2
  const anchorY = rect.height / 2
  setView((v) => {
    if (v.zoom === 1) return v
    const worldX = (anchorX - v.x) / v.zoom
    const worldY = (anchorY - v.y) / v.zoom
    return { zoom: 1, x: anchorX - worldX, y: anchorY - worldY }
  })
}

// Shift+Z toggles: first press pins zoom at 100% (remembering the prior
// view), a second press resumes exactly where the user left off.
function toggleZoom() {
  setView((v) => {
    if (v.zoom !== 1) {
      savedViewRef.current = v
      const rect = boardElRef.current.getBoundingClientRect()
      const anchorX = rect.width / 2
      const anchorY = rect.height / 2
      const worldX = (anchorX - v.x) / v.zoom
      const worldY = (anchorY - v.y) / v.zoom
      return { zoom: 1, x: anchorX - worldX, y: anchorY - worldY }
    }
    if (savedViewRef.current) {
      const saved = savedViewRef.current
      savedViewRef.current = null
      return saved
    }
    return v
  })
}

function getSiblingRects(excludeIds) {
  const excludeSet = excludeIds instanceof Set ? excludeIds : new Set(excludeIds)
  const rects = []
  cardElsRef.current.forEach((el, id) => {
    if (excludeSet.has(id)) return
    rects.push({ x: el.offsetLeft, y: el.offsetTop, width: el.offsetWidth, height: el.offsetHeight })
  })
  return rects
}

// When dragging a card that's part of a multi-selection, every other
// selected card should ride along, keeping the group's relative layout.
function getGroupOrigins(id) {
  if (!selectedIds.has(id) || selectedIds.size <= 1) return []
  return board.cards
    .filter((c) => c.id !== id && selectedIds.has(c.id))
    .map((c) => ({ id: c.id, x: c.x, y: c.y }))
}

function handleCardSelect(id, additive) {
  onSelectionChange((prev) => {
    if (additive) {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    }
    // Clicking (without dragging) a card that's already part of a
    // multi-selection keeps the group intact, so it can be dragged as one.
    if (prev.has(id) && prev.size > 1) return prev
    return new Set([id])
  })

