const WHEEL_ZOOM_INTENSITY = 0.0015
const MARQUEE_DRAG_THRESHOLD = 3

const SHORTCUTS = [
  ['Double-click canvas', 'Create a new note'],
  ['Drag on canvas', 'Select multiple notes'],
  ['Shift + click / drag', 'Add to selection'],
  ['Drag a note', 'Move selected note(s)'],
  ['Right-click + drag', 'Pan the canvas'],
  ['Scroll', 'Zoom in / out'],
  ['⌘/Ctrl + D', 'Duplicate selected note(s)'],
  ['⌘/Ctrl + Enter', 'Reset zoom to 100%'],
  ['⌘/Ctrl + =', 'Pan to center of all notes'],
  ['Backspace / Delete', 'Delete selected note(s)'],
]

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value))
