import { chromium } from 'playwright';

const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
page.on('console', (msg) => console.log('CONSOLE', msg.type(), msg.text()));
page.on('pageerror', (err) => console.log('PAGEERROR', err.message));

await page.goto('http://localhost:5173');
await page.waitForSelector('.board');

const boardBox = await page.locator('.board').boundingBox();
console.log('boardBox', boardBox);

// pan the view a bit first via right-click drag so it's not already centered by default
const cardCount = await page.locator('.card').count();
console.log('cardCount', cardCount);

const bboxBefore = await page.evaluate(() => {
  const cards = [...document.querySelectorAll('.card')];
  let left = Infinity, top = Infinity, right = -Infinity, bottom = -Infinity;
  for (const el of cards) {
    left = Math.min(left, el.offsetLeft);
    top = Math.min(top, el.offsetTop);
    right = Math.max(right, el.offsetLeft + el.offsetWidth);
    bottom = Math.max(bottom, el.offsetTop + el.offsetHeight);
  }
  return { left, top, right, bottom };
});
console.log('card world bbox', bboxBefore);

// zoom out a bit and pan away first (simulate wheel zoom + drag) to make sure content isn't already centered
await page.mouse.move(600, 400);
await page.mouse.wheel(0, 300); // zoom out
await page.waitForTimeout(200);

// pan via right-click drag
await page.mouse.move(600, 400);
await page.mouse.down({ button: 'right' });
await page.mouse.move(200, 100, { steps: 10 });
await page.mouse.up({ button: 'right' });
await page.waitForTimeout(200);

const viewBefore = await page.evaluate(() => {
  const layer = document.querySelector('.board__layer');
  return layer.style.transform;
});
console.log('view before shortcut', viewBefore);

await page.screenshot({ path: '/tmp/before.png' });

// trigger the shortcut
await page.keyboard.down('Control');
await page.keyboard.down('Shift');
await page.keyboard.press('Enter');
await page.keyboard.up('Shift');
await page.keyboard.up('Control');
await page.waitForTimeout(300);

const viewAfter = await page.evaluate(() => {
  const layer = document.querySelector('.board__layer');
  return layer.style.transform;
});
console.log('view after shortcut', viewAfter);

await page.screenshot({ path: '/tmp/after.png' });

await browser.close();

