  cursor: pointer;
  padding: 0;
}

.swatch--active {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
}

/* ---------- board ---------- */

.board {
  position: relative;
  flex: 1 1 auto;
  overflow: hidden;
  min-height: 0;
  background-image: radial-gradient(var(--dot) 1px, transparent 1px);
}

.board--panning {
  cursor: grabbing;
}

.board__layer {
  position: absolute;
  inset: 0;
  transform-origin: 0 0;
}

.board__marquee {
  position: absolute;
  background: color-mix(in srgb, var(--ink) 10%, transparent);
  border: 1px solid var(--outline);
  pointer-events: none;
}

.board__zoom {
  position: absolute;
  right: 14px;
  bottom: 14px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.board__zoom-btn {
  font-family: inherit;
  font-size: 0.9rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--border-soft);
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  cursor: pointer;
}

.board__zoom-btn:hover {
  background: var(--surface-hover);
}

.board__help {
  position: absolute;
  left: 14px;
  bottom: 14px;
}

.help-backdrop {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  z-index: 30;
}

.help-panel {
  width: min(480px, 90%);
  max-height: 80%;
  overflow: auto;
  padding: 24px 28px;
  background: var(--surface);
  border: 2px solid var(--outline);
  border-radius: var(--radius);
}

.help-panel__title {
  margin: 0 0 16px;
  font-size: 1.05rem;
  font-weight: 700;
}

.help-panel__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
  line-height: 1.4;
}

.help-panel__table td {
  padding: 10px 12px;
  vertical-align: top;
}

.help-panel__table tr:nth-child(even) {
  background: var(--dot);
}

.help-panel__key {
  white-space: nowrap;
  padding-right: 24px;
}

.board__zoom-btn--reset {
  width: auto;
  padding: 0 8px;
  font-size: 0.75rem;
}

/* ---------- card ---------- */

.card {
  position: absolute;
  background: var(--surface);
  color: var(--ink);
  border: 3px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  padding: 0;
  cursor: grab;
  user-select: none;
  transition: background-color 0.1s ease;
