import { useRef, useState } from 'react'
import { COLORS, GROUP_MIN_W, GROUP_MIN_H, snapToGrid } from '../data/board.js'
import { patternBackgroundImage } from '../data/patterns.js'

// Each handle adjusts the edges named in its `dir` (e.g. 'se' moves both the
// south and east edges). Corners combine two single-edge adjustments.
const HANDLES = ['n', 's', 'e', 'w', 'ne', 'nw', 'se', 'sw']

function snapSize(value) {
  return Math.max(GROUP_MIN_W, Math.round(value / GROUP_MIN_W) * GROUP_MIN_W)
}

export default function Group({ group, zoom, selected, onSelect, onMove, onResize, registerRef }) {
  const dragRef = useRef(null)
  const resizeRef = useRef(null)
  const [dragging, setDragging] = useState(false)

  function handleBodyPointerDown(e) {
    // Cmd/Ctrl+drag anywhere on the canvas draws a *new* group — don't let
    // an existing group underneath intercept that gesture.
    if (e.metaKey || e.ctrlKey) return
    if (e.button !== 0) return
    onSelect?.(e.shiftKey)
    if (e.target.closest('.group__handle')) return
    dragRef.current = { startX: e.clientX, startY: e.clientY, originX: group.x, originY: group.y }
    setDragging(true)
    e.target.setPointerCapture(e.pointerId)
  }

  function handleBodyPointerMove(e) {
    if (!dragRef.current) return
    const { startX, startY, originX, originY } = dragRef.current
    const dx = (e.clientX - startX) / zoom
    const dy = (e.clientY - startY) / zoom
    onMove(group.id, snapToGrid(originX + dx), snapToGrid(originY + dy))
  }

  function handleBodyPointerUp(e) {
    dragRef.current = null
    setDragging(false)
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  function handleHandlePointerDown(dir, e) {
    e.stopPropagation()
    if (e.button !== 0) return
    resizeRef.current = {
      dir,
      startX: e.clientX,
      startY: e.clientY,
      origin: { x: group.x, y: group.y, w: group.w, h: group.h },
    }
    e.target.setPointerCapture(e.pointerId)
  }

  function handleHandlePointerMove(e) {
    const state = resizeRef.current
    if (!state) return
    const { dir, startX, startY, origin } = state
    const dx = (e.clientX - startX) / zoom
    const dy = (e.clientY - startY) / zoom

    let { x, y, w, h } = origin

    if (dir.includes('e')) w = origin.w + dx
    if (dir.includes('s')) h = origin.h + dy
    if (dir.includes('w')) {
      w = origin.w - dx
      if (w < GROUP_MIN_W) {
        x = origin.x + origin.w - GROUP_MIN_W
        w = GROUP_MIN_W
      } else {
        x = origin.x + dx
      }
    }
    if (dir.includes('n')) {
      h = origin.h - dy
      if (h < GROUP_MIN_H) {
        y = origin.y + origin.h - GROUP_MIN_H
        h = GROUP_MIN_H
      } else {
        y = origin.y + dy
      }
    }

    w = Math.max(GROUP_MIN_W, w)
    h = Math.max(GROUP_MIN_H, h)

    onResize(group.id, { x: snapToGrid(x), y: snapToGrid(y), w: snapSize(w), h: snapSize(h) })
  }

  function handleHandlePointerUp(e) {
    resizeRef.current = null
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  const accent = COLORS[group.color]
  const patternImage = patternBackgroundImage(group.pattern, accent)

  return (
    <div
      ref={registerRef}
      className={`group${dragging ? ' group--dragging' : ''}${selected ? ' group--selected' : ''}`}
      style={{
        left: group.x,
        top: group.y,
        width: group.w,
        height: group.h,
        borderColor: accent,
        backgroundImage: patternImage === 'none' ? undefined : patternImage,
      }}
      onPointerDown={handleBodyPointerDown}
      onPointerMove={handleBodyPointerMove}
      onPointerUp={handleBodyPointerUp}
    >
      {selected &&
        HANDLES.map((dir) => (
          <div
            key={dir}
            className={`group__handle group__handle--${dir}`}
            onPointerDown={(e) => handleHandlePointerDown(dir, e)}
            onPointerMove={handleHandlePointerMove}
            onPointerUp={handleHandlePointerUp}
          />
        ))}
    </div>
  )
}

