    resizeRef.current = null
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  const accent = COLORS[group.color]
  const patternImage = patternBackgroundImage(group.pattern, accent)

  return (
    <div
      ref={registerRef}
      className={`group${dragging ? ' group--dragging' : ''}${selected ? ' group--selected' : ''}`}
      style={{
        left: group.x,
        top: group.y,
        width: group.w,
        height: group.h,
        borderColor: accent,
        backgroundImage: patternImage === 'none' ? undefined : patternImage,
      }}
      onPointerDown={handleBodyPointerDown}
      onPointerMove={handleBodyPointerMove}
      onPointerUp={handleBodyPointerUp}
    >
      {selected &&
        HANDLES.map((dir) => (
          <div
            key={dir}
            className={`group__handle group__handle--${dir}`}
            onPointerDown={(e) => handleHandlePointerDown(dir, e)}
            onPointerMove={handleHandlePointerMove}
            onPointerUp={handleHandlePointerUp}
          />
        ))}
    </div>
  )
}

