.board__zoom-btn {
  font-family: inherit;
  font-size: 0.9rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--border-soft);
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  cursor: pointer;
}

.board__zoom-btn:hover {
  background: var(--surface-hover);
}

.board__help {
  position: absolute;
  left: 14px;
  bottom: 14px;
}

.help-backdrop {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  z-index: 30;
}

.help-panel {
  width: min(480px, 90%);
  max-height: 80%;
  overflow: auto;
  padding: 24px 28px;
  background: var(--surface);
  border: 2px solid var(--outline);
  border-radius: var(--radius);
}

.help-panel__title {
  margin: 0 0 16px;
  font-size: 1.05rem;
  font-weight: 700;
}

.help-panel__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
