.help-panel__table td {
  padding: 10px 12px;
  vertical-align: top;
}

.help-panel__table tr:nth-child(even) {
  background: var(--dot);
}

.help-panel__key {
  white-space: nowrap;
  padding-right: 24px;
}

.board__zoom-btn--reset {
  width: auto;
  padding: 0 8px;
  font-size: 0.75rem;
}

/* ---------- card ---------- */

.card {
  position: absolute;
  background: var(--surface);
  color: var(--ink);
  border: 3px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  padding: 0;
  cursor: grab;
  user-select: none;
  transition: background-color 0.1s ease;
}

.card:hover {
  background: var(--surface-hover);
}

.card--selected {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
  z-index: 5;
}

.card-color-menu {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 6px;
  background: var(--surface);
  border: 2px solid var(--outline);
  border-radius: var(--radius);
  z-index: 20;
}

.card--dragging {
  cursor: grabbing;
  z-index: 10;
}

.card__bar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 10px;
  padding: 1px 3px;
  background: var(--dot);
  border-bottom: 1px solid var(--border-soft);
}

.card__content {
  display: block;
  width: 100%;
  min-height: 64px;
  border: none;
  resize: none;
  overflow: hidden;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 8px;
  background: transparent;
  cursor: text;
}

.card__content:focus {
  outline: none;
