import { useEffect, useState } from 'react'
import { useBoard } from './state/useBoard.js'
import { useTheme } from './state/useTheme.js'
import { isEditableTarget } from './utils/dom.js'
import Board from './components/Board.jsx'
import Toolbar from './components/Toolbar.jsx'

export default function App() {
  const { board, addCard, addGroup, duplicateCards, updateCard, moveCard, updateGroup, removeItems, resetBoard } =
    useBoard()
  const { theme, toggleTheme } = useTheme()
  const [selectedIds, setSelectedIds] = useState(() => new Set())

  useEffect(() => {
    function onKeyDown(e) {
      if (selectedIds.size === 0) return
      const mod = e.metaKey || e.ctrlKey

      if (mod && e.key.toLowerCase() === 'd') {
        e.preventDefault()
        const newIds = duplicateCards([...selectedIds])
        if (newIds.length) setSelectedIds(new Set(newIds))
        return
      }

      if (!mod && (e.key === 'Backspace' || e.key === 'Delete') && !isEditableTarget(e.target)) {
        e.preventDefault()
        removeItems([...selectedIds])
        setSelectedIds(new Set())
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [duplicateCards, removeItems, selectedIds])

  function handleCreateCard(x, y) {
    setSelectedIds(new Set([addCard({ x, y })]))
  }

  function handleCreateGroup(rect) {
    setSelectedIds(new Set([addGroup(rect)]))
  }

  return (
    <div className="app">
      <Toolbar onReset={resetBoard} theme={theme} onToggleTheme={toggleTheme} />
      <Board
        board={board}
        selectedIds={selectedIds}
        onSelectionChange={setSelectedIds}
        onCreateCard={handleCreateCard}
        onCreateGroup={handleCreateGroup}
        actions={{ updateCard, moveCard, updateGroup }}
      />
    </div>
  )
}

