39	    dragRef.current = null
40	    setDragging(false)
41	    try {
42	      e.target.releasePointerCapture(e.pointerId)
43	    } catch {
44	      // ignore
45	    }
46	  }
47	
48	  function handleHandlePointerDown(dir, e) {
49	    e.stopPropagation()
50	    if (e.button !== 0) return
51	    resizeRef.current = {
