export function newCard({ x, y, color = DEFAULT_COLOR } = {}) {
  return {
    id: nextId('c'),
    x: snapToGrid(x ?? 120),
    y: snapToGrid(y ?? 120),
    w: CARD_WIDTH,
    color,
    content: '',
  }
}

export function newGroup({ x, y, w, h, color = DEFAULT_GROUP_COLOR, pattern = DEFAULT_PATTERN } = {}) {
  return {
    id: nextId('g'),
    x: snapToGrid(x ?? 120),
    y: snapToGrid(y ?? 120),
    w: Math.max(GROUP_MIN_W, w ?? GROUP_MIN_W),
    h: Math.max(GROUP_MIN_H, h ?? GROUP_MIN_H),
    color,
    pattern,
  }
