// When dragging a card that's part of a multi-selection, every other
// selected card should ride along, keeping the group's relative layout.
function getGroupOrigins(id) {
  if (!selectedIds.has(id) || selectedIds.size <= 1) return []
  return board.cards
    .filter((c) => c.id !== id && selectedIds.has(c.id))
    .map((c) => ({ id: c.id, x: c.x, y: c.y }))
}

function handleSelect(id, additive) {
  onSelectionChange((prev) => {
    if (additive) {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    }
    // Clicking (without dragging) a card that's already part of a
    // multi-selection keeps the group intact, so it can be dragged as one.
    if (prev.has(id) && prev.size > 1) return prev
    return new Set([id])
  })
}

