      id="edge-arrow"
      viewBox="0 0 10 10"
      refX="8"
      refY="5"
      markerWidth="7"
      markerHeight="7"
      orient="auto-start-reverse"
    >
      <path d="M0,0 L10,5 L0,10 Z" className="edge__arrowhead" />
    </marker>
  </defs>
  {board.edges.map((edge) => {
    const pts = computeEdgeEndpoints(edge)
    if (!pts) return null
    return (
      <Edge
        key={edge.id}
        edge={edge}
        d={curvedPath(edge.id, pts.pA, pts.pB)}
        selected={selectedIds.has(edge.id)}
        onSelect={(additive) => handleSelect(edge.id, additive)}
      />
    )
  })}

