29	    if (e.target.closest('.group__handle')) return
30	    // If this group is part of a multi-selection, the rest of the
31	    // selection (cards and groups alike) moves along with it.
32	    const carryOrigins = getSelectionOrigins?.(group.id) ?? []
33	    dragRef.current = { startX: e.clientX, startY: e.clientY, originX: group.x, originY: group.y, carryOrigins }
34	    setDragging(true)
35	    e.target.setPointerCapture(e.pointerId)
36	  }
37	
38	  function handleBodyPointerMove(e) {
39	    if (!dragRef.current) return
40	    const { startX, startY, originX, originY, carryOrigins } = dragRef.current
41	    const dx = (e.clientX - startX) / zoom
42	    const dy = (e.clientY - startY) / zoom
43	    const snappedX = snapToGrid(originX + dx)
44	    const snappedY = snapToGrid(originY + dy)
45	    onMove(group.id, snappedX, snappedY)
46	
47	    const deltaX = snappedX - originX
48	    const deltaY = snappedY - originY
49	    for (const o of carryOrigins) {
50	      onMove(o.id, o.x + deltaX, o.y + deltaY)
51	    }
52	  }
53	
54	  function handleBodyPointerUp(e) {
55	    dragRef.current = null
56	    setDragging(false)
57	    try {
58	      e.target.releasePointerCapture(e.pointerId)
59	    } catch {
