// World-space bounding box for a card or group, whichever it is — same
// DOM-measured box used for the selection-menu anchor above.
function getNodeBox(id) {
  const el = cardElsRef.current.get(id) ?? groupElsRef.current.get(id)
  if (!el) return null
  return { left: el.offsetLeft, top: el.offsetTop, width: el.offsetWidth, height: el.offsetHeight }
}

// Both endpoints for an edge, each anchored to whichever of its node's 4
// sides currently faces the other node — recomputed every render, so a
// connection always looks right even after either node moves or resizes.
function computeEdgeEndpoints(edge) {
  const boxA = getNodeBox(edge.fromId)
  const boxB = getNodeBox(edge.toId)
  if (!boxA || !boxB) return null
  const centerA = { x: boxA.left + boxA.width / 2, y: boxA.top + boxA.height / 2 }
  const centerB = { x: boxB.left + boxB.width / 2, y: boxB.top + boxB.height / 2 }
  return {
    pA: anchorPoint(boxA, bestSide(boxA, centerB)),
    pB: anchorPoint(boxB, bestSide(boxB, centerA)),
  }
}

