// Both endpoints between two nodes, each anchored to whichever of its
// node's 4 sides currently faces the other node — recomputed every
// render, so a connection always looks right even after either node
// moves or resizes.
function endpointsBetween(idA, idB) {
  const boxA = getNodeBox(idA)
  const boxB = getNodeBox(idB)
  if (!boxA || !boxB) return null
  const centerA = { x: boxA.left + boxA.width / 2, y: boxA.top + boxA.height / 2 }
  const centerB = { x: boxB.left + boxB.width / 2, y: boxB.top + boxB.height / 2 }
  return {
    pA: anchorPoint(boxA, bestSide(boxA, centerB)),
    pB: anchorPoint(boxB, bestSide(boxB, centerA)),
  }
}

function computeEdgeEndpoints(edge) {
  return endpointsBetween(edge.fromId, edge.toId)
}

