import { useLayoutEffect, useRef, useState } from 'react'
import { COLORS, snapToGrid, Y_SNAP_THRESHOLD, Y_SNAP_GUTTER } from '../data/board.js'
import { SIDES } from '../utils/geometry.js'

export default function Card({
  card,
  zoom,
  selected,
  connectTarget,
  onSelect,
  onMove,
  onUpdate,
  getSiblingRects,
  getSelectionOrigins,
  registerRef,
}) {
  const dragRef = useRef(null)
  const contentRef = useRef(null)
  const cardElRef = useRef(null)
  const [dragging, setDragging] = useState(false)
  const [hovered, setHovered] = useState(false)

  function setCardEl(el) {
    cardElRef.current = el
    registerRef?.(el)
  }

  useLayoutEffect(() => {
    const el = contentRef.current
    if (!el) return
    el.style.height = 'auto'
    el.style.height = `${el.scrollHeight}px`
  }, [card.content, card.w])

  function handlePointerDown(e) {
    // only the left button drags a card; right-click is reserved for canvas panning
    if (e.button !== 0) return
    // Cmd/Ctrl+drag anywhere on the canvas draws a new grouping box — don't
    // let a card underneath intercept that gesture.
    if (e.metaKey || e.ctrlKey) return
    // Dragging from a connector dot draws a connection — let it bubble up
    // to Board instead of selecting/moving this card.
    if (e.target.closest('.node-connector')) return
    onSelect?.(e.shiftKey)
    // don't start a drag from interactive children
    if (e.target.closest('.no-drag')) return
    const startX = e.clientX
    const startY = e.clientY
    const originX = card.x
    const originY = card.y
    // If this card is part of a multi-selection, the rest of the selection
    // (cards and groups alike) moves along with it, preserving their
    // relative layout.
    const carryOrigins = getSelectionOrigins?.(card.id) ?? []
    const excludeIds = [card.id, ...carryOrigins.map((o) => o.id)]
    dragRef.current = { startX, startY, originX, originY, carryOrigins, excludeIds }
    setDragging(true)
    e.target.setPointerCapture(e.pointerId)
  }

  function handlePointerMove(e) {
    if (!dragRef.current) return
    const { startX, startY, originX, originY, carryOrigins, excludeIds } = dragRef.current
    // Screen-space pointer movement maps to a smaller world-space movement
    // as the canvas zooms in, and a larger one as it zooms out.
    const dx = (e.clientX - startX) / zoom
    const dy = (e.clientY - startY) / zoom
    const rawX = originX + dx
    const rawY = originY + dy
    const snappedX = snapToGrid(rawX)

    // Vertical position doesn't follow the dot grid: cards vary in height,
    // so instead we look for a neighboring card sharing this column and, if
    // one is within Y_SNAP_THRESHOLD, snap to a fixed gutter from its edge.
    let finalY = snapToGrid(rawY)
    let bestDist = Infinity
    const selfHeight = cardElRef.current?.offsetHeight ?? 0
    const siblings = getSiblingRects?.(excludeIds) ?? []

    for (const s of siblings) {
      const overlapsColumn = snappedX < s.x + s.width && snappedX + card.w > s.x
      if (!overlapsColumn) continue

      const gapBelow = rawY - (s.y + s.height)
      if (Math.abs(gapBelow) < Y_SNAP_THRESHOLD) {
        const candidate = s.y + s.height + Y_SNAP_GUTTER
        const dist = Math.abs(rawY - candidate)
        if (dist < bestDist) {
          bestDist = dist
          finalY = candidate
        }
      }

      const gapAbove = s.y - (rawY + selfHeight)
      if (Math.abs(gapAbove) < Y_SNAP_THRESHOLD) {
        const candidate = s.y - Y_SNAP_GUTTER - selfHeight
        const dist = Math.abs(rawY - candidate)
        if (dist < bestDist) {
          bestDist = dist
          finalY = candidate
        }
      }
    }

    onMove(card.id, snappedX, finalY)

    // Carry the rest of the selection along by the same delta, keeping
    // their positions relative to this (snapped) card unchanged.
    const deltaX = snappedX - originX
    const deltaY = finalY - originY
    for (const o of carryOrigins) {
      onMove(o.id, o.x + deltaX, o.y + deltaY)
    }
  }

  function handlePointerUp(e) {
    dragRef.current = null
    setDragging(false)
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  return (
    <div
      ref={setCardEl}
      data-node-id={card.id}
      className={`card${dragging ? ' card--dragging' : ''}${selected ? ' card--selected' : ''}`}
      style={{ left: card.x, top: card.y, width: card.w, borderColor: COLORS[card.color] }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
    >
      <div className="card__bar" />

      <textarea
        ref={contentRef}
        className="card__content no-drag"
        value={card.content}
        placeholder="Write something..."
        onChange={(e) => onUpdate(card.id, { content: e.target.value })}
        rows={1}
      />

      {(hovered || selected) &&
        SIDES.map((side) => (
          <div key={side} className={`node-connector node-connector--${side}`} data-node-id={card.id} />
        ))}
    </div>
  )
}

import { useRef, useState } from 'react'
import { COLORS, GROUP_MIN_W, GROUP_MIN_H, GRID_SIZE, snapToGrid } from '../data/board.js'
import { patternBackgroundImage } from '../data/patterns.js'
import { SIDES } from '../utils/geometry.js'

// Each handle adjusts the edges named in its `dir` (e.g. 'se' moves both the
// south and east edges). Corners combine two single-edge adjustments.
const HANDLES = ['n', 's', 'e', 'w', 'ne', 'nw', 'se', 'sw']

function snapSize(value, min) {
  return Math.max(min, Math.round(value / GRID_SIZE) * GRID_SIZE)
}

export default function Group({ group, zoom, selected, onSelect, onMove, onResize, getSelectionOrigins, registerRef }) {
  const dragRef = useRef(null)
  const resizeRef = useRef(null)
  const [dragging, setDragging] = useState(false)
  const [hovered, setHovered] = useState(false)

  function handleBodyPointerDown(e) {
    // Cmd/Ctrl+drag anywhere on the canvas draws a *new* group — don't let
    // an existing group underneath intercept that gesture.
    if (e.metaKey || e.ctrlKey) return
    if (e.button !== 0) return
    // Dragging from a connector dot draws a connection — let it bubble up
    // to Board instead of selecting/moving this group.
    if (e.target.closest('.node-connector')) return
    onSelect?.(e.shiftKey)
    if (e.target.closest('.group__handle')) return
    // If this group is part of a multi-selection, the rest of the
    // selection (cards and groups alike) moves along with it.
    const carryOrigins = getSelectionOrigins?.(group.id) ?? []
    dragRef.current = { startX: e.clientX, startY: e.clientY, originX: group.x, originY: group.y, carryOrigins }
    setDragging(true)
    e.target.setPointerCapture(e.pointerId)
  }

  function handleBodyPointerMove(e) {
    if (!dragRef.current) return
    const { startX, startY, originX, originY, carryOrigins } = dragRef.current
    const dx = (e.clientX - startX) / zoom
    const dy = (e.clientY - startY) / zoom
    const snappedX = snapToGrid(originX + dx)
    const snappedY = snapToGrid(originY + dy)
    onMove(group.id, snappedX, snappedY)

    const deltaX = snappedX - originX
    const deltaY = snappedY - originY
    for (const o of carryOrigins) {
      onMove(o.id, o.x + deltaX, o.y + deltaY)
    }
  }

  function handleBodyPointerUp(e) {
    dragRef.current = null
    setDragging(false)
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  function handleHandlePointerDown(dir, e) {
    e.stopPropagation()
    if (e.button !== 0) return
    resizeRef.current = {
      dir,
      startX: e.clientX,
      startY: e.clientY,
      origin: { x: group.x, y: group.y, w: group.w, h: group.h },
    }
    e.target.setPointerCapture(e.pointerId)
  }

  function handleHandlePointerMove(e) {
    const state = resizeRef.current
    if (!state) return
    const { dir, startX, startY, origin } = state
    const dx = (e.clientX - startX) / zoom
    const dy = (e.clientY - startY) / zoom

    let { x, y, w, h } = origin

    if (dir.includes('e')) w = origin.w + dx
    if (dir.includes('s')) h = origin.h + dy
    if (dir.includes('w')) {
      w = origin.w - dx
      if (w < GROUP_MIN_W) {
        x = origin.x + origin.w - GROUP_MIN_W
        w = GROUP_MIN_W
      } else {
        x = origin.x + dx
      }
    }
    if (dir.includes('n')) {
      h = origin.h - dy
      if (h < GROUP_MIN_H) {
        y = origin.y + origin.h - GROUP_MIN_H
        h = GROUP_MIN_H
      } else {
        y = origin.y + dy
      }
    }

    w = Math.max(GROUP_MIN_W, w)
    h = Math.max(GROUP_MIN_H, h)

    onResize(group.id, {
      x: snapToGrid(x),
      y: snapToGrid(y),
      w: snapSize(w, GROUP_MIN_W),
      h: snapSize(h, GROUP_MIN_H),
    })
  }

  function handleHandlePointerUp(e) {
    resizeRef.current = null
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  const accent = COLORS[group.color]
  const patternImage = patternBackgroundImage(group.pattern, accent)

  return (
    <div
      ref={registerRef}
      data-node-id={group.id}
      className={`group${dragging ? ' group--dragging' : ''}${selected ? ' group--selected' : ''}`}
      style={{
        left: group.x,
        top: group.y,
        width: group.w,
        height: group.h,
        borderColor: accent,
        backgroundImage: patternImage === 'none' ? undefined : patternImage,
      }}
      onPointerDown={handleBodyPointerDown}
      onPointerMove={handleBodyPointerMove}
      onPointerUp={handleBodyPointerUp}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
    >
      {selected &&
        HANDLES.map((dir) => (
          <div
            key={dir}
            className={`group__handle group__handle--${dir}`}
            onPointerDown={(e) => handleHandlePointerDown(dir, e)}
            onPointerMove={handleHandlePointerMove}
            onPointerUp={handleHandlePointerUp}
          />
        ))}

      {/* Resize handles occupy the same N/E/S/W slots while selected, so
          connectors only show up unselected+hovered to avoid overlapping them. */}
      {hovered &&
        !selected &&
        SIDES.map((side) => (
          <div key={side} className={`node-connector node-connector--${side}`} data-node-id={group.id} />
        ))}
    </div>
  )
}

