import { useCallback, useEffect, useState } from 'react'
import { seedBoard, newCard, newGroup, newEdge, nextId, snapToGrid, GRID_SIZE } from '../data/board.js'

const STORAGE_KEY = 'kanvy.board'

function loadInitialBoard() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw)
      // Boards saved before grouping boxes/connections existed won't have
      // `groups`/`edges` arrays.
      return { groups: [], edges: [], ...parsed }
    }
  } catch {
    // ignore corrupt storage, fall back to seed
  }
  return seedBoard
}

export function useBoard() {
  const [board, setBoard] = useState(loadInitialBoard)

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(board))
  }, [board])

  const addCard = useCallback((opts) => {
    const card = newCard(opts)
    setBoard((b) => ({ ...b, cards: [...b.cards, card] }))
    return card.id
  }, [])

  const addGroup = useCallback((opts) => {
    const group = newGroup(opts)
    setBoard((b) => ({ ...b, groups: [...b.groups, group] }))
    return group.id
  }, [])

  const duplicateCards = useCallback(
    (ids) => {
      const idSet = new Set(ids)
      const originals = board.cards.filter((c) => idSet.has(c.id))
      if (originals.length === 0) return []
      const duplicates = originals.map((original) => ({
        ...original,
        id: nextId('c'),
        x: snapToGrid(original.x + GRID_SIZE * 2),
        y: snapToGrid(original.y + GRID_SIZE * 2),
      }))
      setBoard((b) => ({ ...b, cards: [...b.cards, ...duplicates] }))
      return duplicates.map((d) => d.id)
    },
    [board],
  )

  const updateCard = useCallback((id, patch) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) => (c.id === id ? { ...c, ...patch } : c)),
    }))
  }, [])

  const moveCard = useCallback((id, x, y) => {
    setBoard((b) => ({
      ...b,
      cards: b.cards.map((c) => (c.id === id ? { ...c, x, y } : c)),
    }))
  }, [])

  const updateGroup = useCallback((id, patch) => {
    setBoard((b) => ({
      ...b,
      groups: b.groups.map((g) => (g.id === id ? { ...g, ...patch } : g)),
    }))
  }, [])

  const addEdge = useCallback((fromId, toId) => {
    const edge = newEdge({ fromId, toId })
    setBoard((b) => ({ ...b, edges: [...b.edges, edge] }))
    return edge.id
  }, [])

  const updateEdge = useCallback((id, patch) => {
    setBoard((b) => ({
      ...b,
      edges: b.edges.map((ed) => (ed.id === id ? { ...ed, ...patch } : ed)),
    }))
  }, [])

  const removeItems = useCallback((ids) => {
    const idSet = new Set(ids)
    setBoard((b) => ({
      ...b,
      cards: b.cards.filter((c) => !idSet.has(c.id)),
      groups: b.groups.filter((g) => !idSet.has(g.id)),
      // Also drops any edge attached to a card/group that got deleted, not
      // just edges the user selected directly.
      edges: b.edges.filter((ed) => !idSet.has(ed.id) && !idSet.has(ed.fromId) && !idSet.has(ed.toId)),
    }))
  }, [])

  const resetBoard = useCallback(() => {
    setBoard(seedBoard)
  }, [])

  return {
    board,
    addCard,
    addGroup,
    addEdge,
    duplicateCards,
    updateCard,
    moveCard,
    updateGroup,
    updateEdge,
    removeItems,
    resetBoard,
  }
}

