// World-space bounding box for a card or group, whichever it is — same
// DOM-measured box used for the selection-menu anchor above.
function getNodeBox(id) {
  const el = cardElsRef.current.get(id) ?? groupElsRef.current.get(id)
  if (!el) return null
  return { left: el.offsetLeft, top: el.offsetTop, width: el.offsetWidth, height: el.offsetHeight }
}

// Both endpoints between two nodes, each anchored to whichever of its
// node's 4 sides currently faces the other node — recomputed every
// render, so a connection always looks right even after either node
// moves or resizes.
function endpointsBetween(idA, idB) {
  const boxA = getNodeBox(idA)
  const boxB = getNodeBox(idB)
