export const SIDES = ['top', 'right', 'bottom', 'left']

export function anchorPoint(box, side) {
  const cx = box.left + box.width / 2
  const cy = box.top + box.height / 2
  switch (side) {
    case 'top':
      return { x: cx, y: box.top }
    case 'bottom':
      return { x: cx, y: box.top + box.height }
    case 'left':
      return { x: box.left, y: cy }
    case 'right':
      return { x: box.left + box.width, y: cy }
    default:
      return { x: cx, y: cy }
  }
}

export function boxCenter(box) {
  return { x: box.left + box.width / 2, y: box.top + box.height / 2 }
}

// Whichever of a box's 4 sides faces `point` most directly. Used only as a
// fallback when a connection is dropped onto a node without landing on one
// of its 4 connector dots — an explicit dot always wins, since the user's
// choice of side is deliberate and persists even if it makes the line bend
// around rather than take the shortest path.
export function bestSide(box, point) {
  const cx = box.left + box.width / 2
  const cy = box.top + box.height / 2
  const dx = point.x - cx
  const dy = point.y - cy
  if (Math.abs(dx) > Math.abs(dy)) return dx >= 0 ? 'right' : 'left'
  return dy >= 0 ? 'bottom' : 'top'
}

function hashSeed(id) {
  let h = 0
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) | 0
  return h
}

// A gentle quadratic-bezier bow, bent perpendicular to the straight line
// between the two points. The bend's direction and magnitude are derived
// from a hash of `seed` (the edge id) so it's stable across renders but
// varies edge-to-edge — organic curvature with no user-facing control.
export function curvedPath(seed, p1, p2) {
  const dx = p2.x - p1.x
  const dy = p2.y - p1.y
  const dist = Math.hypot(dx, dy) || 1
  const midX = (p1.x + p2.x) / 2
  const midY = (p1.y + p2.y) / 2
  const nx = -dy / dist
  const ny = dx / dist
  const sign = hashSeed(seed) % 2 === 0 ? 1 : -1
  const bend = sign * Math.min(60, dist * 0.18)
  const cx = midX + nx * bend
  const cy = midY + ny * bend
  return `M ${p1.x} ${p1.y} Q ${cx} ${cy} ${p2.x} ${p2.y}`
}

