function handlePointerUp(e) {
  if (connectingRef.current) {
    const { fromId, fromSide } = connectingRef.current
    connectingRef.current = null
    setConnectingPreview(null)
    // Dropping precisely on one of the target's 4 connector dots picks
    // that exact side; dropping anywhere else on its body falls back to
    // whichever side faces the source node.
    const hitEl = document.elementFromPoint(e.clientX, e.clientY)
    const dotEl = hitEl?.closest('.node-connector')
    const nodeEl = hitEl?.closest('.card, .group')
    let toId = null
    let toSide = null
    if (dotEl && dotEl.dataset.nodeId !== fromId) {
      toId = dotEl.dataset.nodeId
      toSide = dotEl.dataset.side
    } else if (nodeEl && nodeEl.dataset.nodeId !== fromId) {
      toId = nodeEl.dataset.nodeId
      toSide = autoSide(toId, fromId)
    }
    if (toId && toSide) onCreateEdge?.(fromId, fromSide, toId, toSide)
    try {
      e.currentTarget.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
    return
  }

