  const dy = p2.y - p1.y
  const dist = Math.hypot(dx, dy) || 1
  const ux = dx / dist
  const uy = dy / dist
  const px = -uy // perpendicular unit vector to p1→p2
  const py = ux

  const jitter = 0.85 + (hashSeed(seed) % 100) / 333 // ~0.85–1.15
