:root {
  color-scheme: light;
  --paper: #eef1f4;
  --ink: #1b1e22;
  --line: #1b1e22;
  --surface: #ffffff;
  --surface-hover: #f2eee6;
  --dot: rgba(15, 18, 22, 0.08);
  --border-soft: rgba(27, 30, 34, 0.2);
  --outline: rgba(27, 30, 34, 0.45);
  --radius: 5px;
  font-family: 'Fira Code', 'Courier New', monospace;
}

[data-theme='dark'] {
  color-scheme: dark;
  --paper: #1a1d22;
  --ink: #e8ebef;
  --line: #e8ebef;
  --surface: #262a31;
  --surface-hover: #2f343c;
  --dot: rgba(255, 255, 255, 0.08);
  --border-soft: rgba(232, 235, 239, 0.25);
  --outline: rgba(232, 235, 239, 0.35);
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  transition: background-color 0.15s ease, color 0.15s ease;
}

.app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

/* ---------- toolbar ---------- */

.toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--paper);
  border-bottom: 2px solid var(--border-soft);
}

.toolbar__brand {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  margin-right: 8px;
}

.toolbar__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  font-size: 0.85rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 6px 12px;
  cursor: pointer;
  transition: background-color 0.1s ease;
}

.toolbar__btn--icon {
  padding: 6px 10px;
}

.toolbar__btn:hover {
  background: var(--surface-hover);
}

.toolbar__btn--ghost {
  margin-left: auto;
  background: transparent;
}

.swatch {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--border-soft);
  cursor: pointer;
  padding: 0;
}

.swatch--active {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
}

/* ---------- board ---------- */

.board {
  position: relative;
  flex: 1 1 auto;
  overflow: hidden;
  min-height: 0;
  background-image: radial-gradient(var(--dot) 1px, transparent 1px);
}

.board--panning {
  cursor: grabbing;
}

.board__layer {
  position: absolute;
  inset: 0;
  transform-origin: 0 0;
}

.board__marquee {
  position: absolute;
  background: color-mix(in srgb, var(--ink) 10%, transparent);
  border: 1px solid var(--outline);
  pointer-events: none;
}

.board__group-preview {
  position: absolute;
  background: color-mix(in srgb, var(--outline) 12%, transparent);
  border: 2px dashed var(--outline);
  border-radius: var(--radius);
  pointer-events: none;
}

.board__zoom {
  position: absolute;
  right: 14px;
  bottom: 14px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.board__zoom-btn {
  font-family: inherit;
  font-size: 0.9rem;
  background: var(--surface);
  color: var(--ink);
  border: 2px solid var(--border-soft);
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  cursor: pointer;
}

.board__zoom-btn:hover {
  background: var(--surface-hover);
}

.board__help {
  position: absolute;
  left: 14px;
  bottom: 14px;
}

.help-backdrop {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  z-index: 30;
}

.help-panel {
  width: min(480px, 90%);
  max-height: 80%;
  overflow: auto;
  padding: 24px 28px;
  background: var(--surface);
  border: 2px solid var(--outline);
  border-radius: var(--radius);
}

.help-panel__title {
  margin: 0 0 16px;
  font-size: 1.05rem;
  font-weight: 700;
}

.help-panel__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
  line-height: 1.4;
}

.help-panel__table td {
  padding: 10px 12px;
  vertical-align: top;
}

.help-panel__table tr:nth-child(even) {
  background: var(--dot);
}

.help-panel__key {
  white-space: nowrap;
  padding-right: 24px;
}

.board__zoom-btn--reset {
  width: auto;
  padding: 0 8px;
  font-size: 0.75rem;
}

/* ---------- card ---------- */

.card {
  position: absolute;
  background: var(--surface);
  color: var(--ink);
  border: 3px solid var(--line);
  border-radius: var(--radius);
  padding: 0;
  cursor: grab;
  user-select: none;
  transition: background-color 0.1s ease;
}

/* Clipping lives here rather than on .card itself, so the connector dots
   (siblings of this, direct children of .card) can sit outside the border
   without being cut off. */
.card__inner {
  overflow: hidden;
  border-radius: var(--radius);
}

.card:hover {
  background: var(--surface-hover);
}

.card--selected {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
  z-index: 5;
}

.card--dragging {
  cursor: grabbing;
  z-index: 10;
}

/* Shown on whichever node a connection drag is currently hovering, so it's
   obvious exactly where releasing will attach. */
.card--connect-target {
  outline: 3px solid #4f8888;
  outline-offset: 2px;
}

.card__bar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 10px;
  padding: 1px 3px;
  background: var(--dot);
  border-bottom: 1px solid var(--border-soft);
}

.card__content {
  display: block;
  width: 100%;
  min-height: 64px;
  border: none;
  resize: none;
  overflow: hidden;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 8px;
  background: transparent;
  cursor: text;
}

.card__content:focus {
  outline: none;
}

/* ---------- group ---------- */

/* Never given a z-index — its stacking relies entirely on DOM order (it's
   rendered before cards in Board.jsx) so notes always paint on top of it. */
.group {
  position: absolute;
  background-color: var(--surface);
  background-repeat: repeat;
  border: 3px solid var(--line);
  border-radius: var(--radius);
  cursor: grab;
  user-select: none;
}

.group--dragging {
  cursor: grabbing;
}

.group--selected {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
}

/* Never given a z-index either, for the same reason as .group above. */
.group--connect-target {
  outline: 3px solid #4f8888;
  outline-offset: 2px;
}

.group__handle {
  position: absolute;
}

.group__handle--n,
.group__handle--s {
  left: 10px;
  right: 10px;
  height: 10px;
  cursor: ns-resize;
}

.group__handle--n {
  top: -5px;
}

.group__handle--s {
  bottom: -5px;
}

.group__handle--e,
.group__handle--w {
  top: 10px;
  bottom: 10px;
  width: 10px;
  cursor: ew-resize;
}

.group__handle--e {
  right: -5px;
}

.group__handle--w {
  left: -5px;
}

.group__handle--ne,
.group__handle--nw,
.group__handle--se,
.group__handle--sw {
  width: 14px;
  height: 14px;
}

.group__handle--ne,
.group__handle--sw {
  cursor: nesw-resize;
}

.group__handle--nw,
.group__handle--se {
  cursor: nwse-resize;
}

.group__handle--ne {
  top: -7px;
  right: -7px;
}

.group__handle--nw {
  top: -7px;
  left: -7px;
}

.group__handle--se {
  bottom: -7px;
  right: -7px;
}

.group__handle--sw {
  bottom: -7px;
  left: -7px;
}

.selection-menu {
  position: absolute;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px;
  background: var(--surface);
  border: 2px solid var(--outline);
  border-radius: var(--radius);
  z-index: 20;
}

.selection-menu__grid {
  display: grid;
  grid-template-columns: repeat(3, 20px);
  gap: 6px;
}

.selection-menu__divider {
  height: 1px;
  background: var(--border-soft);
}

.pattern-swatch {
  width: 20px;
  height: 20px;
  border-radius: 4px;
  border: 2px solid var(--border-soft);
  cursor: pointer;
  padding: 0;
  background-color: var(--surface);
  background-repeat: repeat;
}

.pattern-swatch--active {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
}

/* ---------- connectors ---------- */

.node-connector {
  position: absolute;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--surface);
  border: 2px solid var(--outline);
  cursor: crosshair;
  transition: transform 0.08s ease, background-color 0.08s ease;
}

/* The side a connection is about to attach to, while dragging one in. */
.node-connector--active {
  background: #4f8888;
  border-color: #4f8888;
  transform: scale(1.6);
}

.node-connector--top.node-connector--active,
.node-connector--bottom.node-connector--active {
  transform: translateX(-50%) scale(1.6);
}

.node-connector--left.node-connector--active,
.node-connector--right.node-connector--active {
  transform: translateY(-50%) scale(1.6);
}

.node-connector--top,
.node-connector--bottom {
  left: 50%;
  transform: translateX(-50%);
}

.node-connector--top {
  top: -5px;
}

.node-connector--bottom {
  bottom: -5px;
}

.node-connector--left,
.node-connector--right {
  top: 50%;
  transform: translateY(-50%);
}

.node-connector--left {
  left: -5px;
}

.node-connector--right {
  right: -5px;
}

/* ---------- edges (connections between nodes) ---------- */

/* No pointer-events on the SVG root — its transparent area must let clicks
   through to the marquee/pan handling below it. Each edge's own hit-path
   re-enables pointer-events just along its stroke. */
.board__edges {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none;
}

.edge__hit {
  fill: none;
  stroke: transparent;
  stroke-width: 14;
  pointer-events: stroke;
  cursor: pointer;
}

.edge__line {
  fill: none;
  stroke: #888;
  stroke-width: 2;
  pointer-events: none;
}

.edge--selected .edge__line {
  stroke: var(--outline);
  stroke-width: 3;
}

.edge__arrowhead {
  fill: #888;
}

.edge__arrowhead--selected {
  fill: var(--outline);
}

.board__edge-preview {
  fill: none;
  stroke: #888;
  stroke-width: 2;
  stroke-dasharray: 6 4;
}

.edge-menu__btn {
  width: 20px;
  height: 20px;
  border-radius: 4px;
  border: 2px solid var(--border-soft);
  background: var(--surface);
  color: var(--ink);
  font-size: 0.85rem;
  line-height: 1;
  padding: 0;
  cursor: pointer;
}

.edge-menu__btn--active {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
}

