1	import { useRef, useState } from 'react'
2	import { COLORS, GROUP_MIN_W, GROUP_MIN_H, GRID_SIZE, snapToGrid } from '../data/board.js'
3	import { patternBackgroundImage } from '../data/patterns.js'
4	import { SIDES } from '../utils/geometry.js'
5	
6	// Each handle adjusts the edges named in its `dir` (e.g. 'se' moves both the
7	// south and east edges). Corners combine two single-edge adjustments.
8	const HANDLES = ['n', 's', 'e', 'w', 'ne', 'nw', 'se', 'sw']
9	
10	function snapSize(value, min) {
11	  return Math.max(min, Math.round(value / GRID_SIZE) * GRID_SIZE)
12	}
13	
14	export default function Group({
15	  group,
16	  zoom,
17	  selected,
18	  connectTarget,
19	  connectHoverSide,
20	  onSelect,
21	  onMove,
22	  onResize,
23	  getSelectionOrigins,
24	  registerRef,
25	}) {
26	  const dragRef = useRef(null)
27	  const resizeRef = useRef(null)
28	  const [dragging, setDragging] = useState(false)
29	  const [hovered, setHovered] = useState(false)
30	
31	  function handleBodyPointerDown(e) {
32	    // Cmd/Ctrl+drag anywhere on the canvas draws a *new* group — don't let
33	    // an existing group underneath intercept that gesture.
34	    if (e.metaKey || e.ctrlKey) return
35	    if (e.button !== 0) return
36	    // Dragging from a connector dot draws a connection — let it bubble up
37	    // to Board instead of selecting/moving this group.
38	    if (e.target.closest('.node-connector')) return
39	    onSelect?.(e.shiftKey)
40	    if (e.target.closest('.group__handle')) return
41	    // If this group is part of a multi-selection, the rest of the
42	    // selection (cards and groups alike) moves along with it.
43	    const carryOrigins = getSelectionOrigins?.(group.id) ?? []
44	    dragRef.current = { startX: e.clientX, startY: e.clientY, originX: group.x, originY: group.y, carryOrigins }
45	    setDragging(true)
46	    e.target.setPointerCapture(e.pointerId)
47	  }
48	
49	  function handleBodyPointerMove(e) {
50	    if (!dragRef.current) return
51	    const { startX, startY, originX, originY, carryOrigins } = dragRef.current
52	    const dx = (e.clientX - startX) / zoom
53	    const dy = (e.clientY - startY) / zoom
54	    const snappedX = snapToGrid(originX + dx)
55	    const snappedY = snapToGrid(originY + dy)
56	    onMove(group.id, snappedX, snappedY)
57	
58	    const deltaX = snappedX - originX
59	    const deltaY = snappedY - originY
60	    for (const o of carryOrigins) {
61	      onMove(o.id, o.x + deltaX, o.y + deltaY)
62	    }
63	  }
64	
65	  function handleBodyPointerUp(e) {
66	    dragRef.current = null
67	    setDragging(false)
68	    try {
69	      e.target.releasePointerCapture(e.pointerId)
70	    } catch {
71	      // ignore
72	    }
73	  }
74	
75	  function handleHandlePointerDown(dir, e) {
76	    e.stopPropagation()
77	    if (e.button !== 0) return
78	    resizeRef.current = {
79	      dir,
80	      startX: e.clientX,
81	      startY: e.clientY,
82	      origin: { x: group.x, y: group.y, w: group.w, h: group.h },
83	    }
84	    e.target.setPointerCapture(e.pointerId)
85	  }
86	
87	  function handleHandlePointerMove(e) {
88	    const state = resizeRef.current
89	    if (!state) return
90	    const { dir, startX, startY, origin } = state
91	    const dx = (e.clientX - startX) / zoom
92	    const dy = (e.clientY - startY) / zoom
93	
94	    let { x, y, w, h } = origin
95	
96	    if (dir.includes('e')) w = origin.w + dx
97	    if (dir.includes('s')) h = origin.h + dy
98	    if (dir.includes('w')) {
99	      w = origin.w - dx
100	      if (w < GROUP_MIN_W) {
101	        x = origin.x + origin.w - GROUP_MIN_W
102	        w = GROUP_MIN_W
103	      } else {
104	        x = origin.x + dx
105	      }
106	    }
107	    if (dir.includes('n')) {
108	      h = origin.h - dy
109	      if (h < GROUP_MIN_H) {
110	        y = origin.y + origin.h - GROUP_MIN_H
111	        h = GROUP_MIN_H
112	      } else {
113	        y = origin.y + dy
114	      }
115	    }
116	
117	    w = Math.max(GROUP_MIN_W, w)
118	    h = Math.max(GROUP_MIN_H, h)
119	
120	    onResize(group.id, {
121	      x: snapToGrid(x),
122	      y: snapToGrid(y),
123	      w: snapSize(w, GROUP_MIN_W),
124	      h: snapSize(h, GROUP_MIN_H),
125	    })
126	  }
127	
128	  function handleHandlePointerUp(e) {
129	    resizeRef.current = null
130	    try {
131	      e.target.releasePointerCapture(e.pointerId)
132	    } catch {
133	      // ignore
134	    }
135	  }
136	
137	  const accent = COLORS[group.color]
138	  const patternImage = patternBackgroundImage(group.pattern, accent)
139	
140	  return (
141	    <div
