// Pushes `y` down below any group's top exclusion zone (its drag handle
// plus one grid cell of breathing room) that [x, x+w] horizontally
// overlaps — so a note can never be placed touching or under a group's
// drag handle. `zones` is an array of { left, right, minY }.
export function clampYForGroupExclusions(x, w, y, zones) {
  let clamped = y
  for (const zone of zones) {
    const overlapsColumn = x < zone.right && x + w > zone.left
    if (overlapsColumn && clamped < zone.minY) clamped = zone.minY
  }
  return clamped
}

