/* Big text: an explicit height (set inline from card.h) instead of growing
   with content, a large font, and — since it never scrolls internally —
   overflow is just clipped (truncated) rather than given a scrollbar.
   The content area is absolutely positioned to exactly fill the space below
   the bar (17px = card__bar's 16px min-height + 1px border) rather than
   relying on flexbox to shrink it: a <textarea>'s intrinsic content size
   otherwise wins over flex-shrink in most browsers even with min-height: 0,
   which was silently defeating the truncation. */
.card--big .card__inner {
  position: relative;
  height: 100%;
}

.card--big .card__content {
  position: absolute;
  inset: 17px 0 0 0;
  height: auto;
  overflow: hidden;
  font-size: 3rem;
  line-height: 1.2;
}

