import { useEffect, useState } from 'react'
import { useBoard } from './state/useBoard.js'
import { useTheme } from './state/useTheme.js'
import { isEditableTarget } from './utils/dom.js'
import Board from './components/Board.jsx'
import Toolbar from './components/Toolbar.jsx'

export default function App() {
  const {
    board,
    addCard,
    addGroup,
    addEdge,
    duplicateCards,
    copySelection,
    pasteClipboard,
    updateCard,
    moveCard,
    updateGroup,
    updateEdge,
    removeItems,
    undo,
    redo,
  } = useBoard()
  const { theme, toggleTheme } = useTheme()
  const [selectedIds, setSelectedIds] = useState(() => new Set())
  const [focusCardId, setFocusCardId] = useState(null)

  useEffect(() => {
    function onKeyDown(e) {
      const mod = e.metaKey || e.ctrlKey
      const key = e.key.toLowerCase()

      // Undo/redo work regardless of selection, but not while typing in a
      // note — Cmd/Ctrl+Z there should be the browser's native text undo.
      if (mod && (key === 'z' || key === 'y') && !isEditableTarget(e.target)) {
        e.preventDefault()
        if (key === 'y' || e.shiftKey) redo()
        else undo()
        return
      }

      // Paste doesn't depend on the current selection (it works off the
      // clipboard, not selectedIds), so it has to sit before that gate below.
