import { useEffect, useRef, useState } from 'react'
import { useBoard } from './state/useBoard.js'
import { useTheme } from './state/useTheme.js'
import { isEditableTarget } from './utils/dom.js'
import Board from './components/Board.jsx'
import Toolbar from './components/Toolbar.jsx'

export default function App() {
  const {
    board,
    addCard,
    addGroup,
    addEdge,
    duplicateCards,
    copySelection,
    pasteClipboard,
    updateCard,
    moveCard,
    updateGroup,
    updateEdge,
    removeItems,
    undo,
    redo,
  } = useBoard()
  const { theme, toggleTheme } = useTheme()
  const [selectedIds, setSelectedIds] = useState(() => new Set())
  const [focusCardId, setFocusCardId] = useState(null)
  const boardRef = useRef(null)

  useEffect(() => {
    function onKeyDown(e) {
      const mod = e.metaKey || e.ctrlKey
      const key = e.key.toLowerCase()

      // Undo/redo work regardless of selection, but not while typing in a
      // note — Cmd/Ctrl+Z there should be the browser's native text undo.
      if (mod && (key === 'z' || key === 'y') && !isEditableTarget(e.target)) {
        e.preventDefault()
        if (key === 'y' || e.shiftKey) redo()
        else undo()
        return
      }

      // Paste doesn't depend on the current selection (it works off the
      // clipboard, not selectedIds), so it has to sit before that gate below.
      if (mod && key === 'v' && !isEditableTarget(e.target)) {
        e.preventDefault()
        if (selectedIds.size === 0) {
          // Nothing selected reads as "paste something fresh" rather than
          // "continue an in-app node copy/paste" — falls back to the
          // system clipboard's plain text and drops it as a new note,
          // rather than whatever's in our own in-app clipboard.
          pasteSystemClipboardAsCard()
        } else {
          const newIds = pasteClipboard()
          if (newIds.length) setSelectedIds(new Set(newIds))
        }
        return
      }

      if (selectedIds.size === 0) return

      if (mod && key === 'c' && !isEditableTarget(e.target)) {
        e.preventDefault()
        copySelection([...selectedIds])
        writeSelectionTextToSystemClipboard([...selectedIds])
        return
      }

      if (mod && key === 'd') {
        e.preventDefault()
        const newIds = duplicateCards([...selectedIds])
        if (newIds.length) {
          setSelectedIds(new Set(newIds))
          // Jump straight into editing the duplicate rather than leaving it
          // just selected — matches how a fresh copy is usually meant to be
          // tweaked right away.
          setFocusCardId(newIds[0])
        }
        return
      }

      if (!mod && (e.key === 'Backspace' || e.key === 'Delete') && !isEditableTarget(e.target)) {
        e.preventDefault()
        removeItems([...selectedIds])
        setSelectedIds(new Set())
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [duplicateCards, copySelection, pasteClipboard, removeItems, selectedIds, undo, redo, board])

  // System-clipboard integration is layered on top of the existing in-app
  // copy/paste, not a replacement for it — see the keydown handler above
  // for when each path is used.
  function writeSelectionTextToSystemClipboard(ids) {
    if (!navigator.clipboard?.writeText) return
    const idSet = new Set(ids)
    const text = board.cards
      .filter((c) => idSet.has(c.id) && c.content.trim())
      .map((c) => c.content)
      .join('\n\n')
    // Never overwrite the user's system clipboard with nothing just because
    // the selection had no text (e.g. it was only grouping boxes).
    if (!text) return
    navigator.clipboard.writeText(text).catch(() => {
      // Permission denied or unavailable — the in-app copy already
      // succeeded, so there's nothing more to do here.
    })
  }

  async function pasteSystemClipboardAsCard() {
    if (!navigator.clipboard?.readText) return
    try {
      const text = await navigator.clipboard.readText()
      // Reading "text/plain" already discards any rich formatting — always
      // lands as a plain note, per the requirement.
      if (!text || !text.trim()) return
      boardRef.current?.pasteTextAsCard(text)
    } catch {
      // Permission denied, or nothing readable on the clipboard — no-op.
    }
  }

  function handleCreateCard(x, y, content) {
    const id = addCard({ x, y, content })
    setSelectedIds(new Set([id]))
    setFocusCardId(id)
  }

  function handleCreateGroup(rect) {
    setSelectedIds(new Set([addGroup(rect)]))
  }

  function handleCreateEdge(fromId, fromSide, toId, toSide) {
    setSelectedIds(new Set([addEdge(fromId, fromSide, toId, toSide)]))
  }

  function handleDownload() {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-')
    const blob = new Blob([JSON.stringify(board, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `kanvy-board-${timestamp}.json`
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)
  }

  return (
    <div className="app">
      <Toolbar onDownload={handleDownload} theme={theme} onToggleTheme={toggleTheme} />
      <Board
        board={board}
        selectedIds={selectedIds}
        onSelectionChange={setSelectedIds}
        onCreateCard={handleCreateCard}
        onCreateGroup={handleCreateGroup}
        onCreateEdge={handleCreateEdge}
        focusCardId={focusCardId}
        actions={{ updateCard, moveCard, updateGroup, updateEdge }}
      />
    </div>
  )
}

