/* ---------- edges (connections between nodes) ---------- */

/* No pointer-events on the SVG root — its transparent area must let clicks
   through to the marquee/pan handling below it. Each edge's own hit-path
   re-enables pointer-events just along its stroke. */
.board__edges {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none;
}

.edge__hit {
  fill: none;
  stroke: transparent;
  stroke-width: 14;
  pointer-events: stroke;
  cursor: pointer;
}

.edge__line {
  fill: none;
  stroke: #888;
  stroke-width: 2;
  pointer-events: none;
}

.edge--selected .edge__line {
  stroke: var(--outline);
  stroke-width: 3;
}

.edge__arrowhead {
  fill: #888;
}

.edge__arrowhead--selected {
  fill: var(--outline);
}

.board__edge-preview {
  fill: none;
  stroke: #888;
  stroke-width: 2;
  stroke-dasharray: 6 4;
}

