import { useLayoutEffect, useRef, useState } from 'react'
import {
  resolveColor,
  snapToGrid,
  Y_SNAP_THRESHOLD,
  Y_SNAP_GUTTER,
  BIG_TEXT_MIN_W,
  BIG_TEXT_MIN_H,
  GRID_SIZE,
} from '../data/board.js'
import { SIDES, clampYForGroupExclusions } from '../utils/geometry.js'

// Each handle adjusts the edges named in its `dir` (e.g. 'se' moves both the
// south and east edges). Corners combine two single-edge adjustments. Only
// rendered for big-text cards — regular notes are fixed-width/content-height.
const HANDLES = ['n', 's', 'e', 'w', 'ne', 'nw', 'se', 'sw']

function snapSize(value, min) {
  return Math.max(min, Math.round(value / GRID_SIZE) * GRID_SIZE)
}

export default function Card({
  card,
  imageSrc,
  zoom,
  theme,
  selected,
  connectTarget,
  connectHoverSide,
  autoFocus,
  onSelect,
  onMove,
  onUpdate,
  getSiblingRects,
  getSelectionOrigins,
  getGroupExclusions,
  registerRef,
}) {
  const isImage = !!card.imageId
  // An image card is never "big" sized (see convertCardToImage in
  // useBoard.js) — this is just belt-and-suspenders against stale data.
  const isBig = !isImage && card.textSize === 'big'
  const dragRef = useRef(null)
  const resizeRef = useRef(null)
  const contentRef = useRef(null)
  const cardElRef = useRef(null)
  const autoFocusRef = useRef(autoFocus)
  const [dragging, setDragging] = useState(false)
  const [hovered, setHovered] = useState(false)

  function setCardEl(el) {
    cardElRef.current = el
    registerRef?.(el)
  }

  // Regular notes grow to fit their content; big text has an explicit,
  // user-resized height instead, so it never participates in this.
  useLayoutEffect(() => {
    if (isBig) return
    const el = contentRef.current
    if (!el) return
    el.style.height = 'auto'
    el.style.height = `${el.scrollHeight}px`
  }, [card.content, card.w, isBig])

  // Only checked once, at mount — e.g. right after a duplicate is created,
  // so it's immediately ready to edit instead of just sitting selected.
  useLayoutEffect(() => {
    if (!autoFocusRef.current) return
    const el = contentRef.current
    if (!el) return
    el.focus()
    el.setSelectionRange(el.value.length, el.value.length)
  }, [])

  function handlePointerDown(e) {
    // only the left button drags a card; right-click is reserved for canvas panning
    if (e.button !== 0) return
    // Cmd/Ctrl+drag anywhere on the canvas draws a new grouping box — don't
    // let a card underneath intercept that gesture.
    if (e.metaKey || e.ctrlKey) return
    // Dragging from a connector dot draws a connection — let it bubble up
    // to Board instead of selecting/moving this card.
    if (e.target.closest('.node-connector')) return
    onSelect?.(e.shiftKey)
    // don't start a drag from interactive children
    if (e.target.closest('.no-drag')) return
    const startX = e.clientX
    const startY = e.clientY
    const originX = card.x
    const originY = card.y
    // If this card is part of a multi-selection, the rest of the selection
    // (cards and groups alike) moves along with it, preserving their
    // relative layout.
    const carryOrigins = getSelectionOrigins?.(card.id) ?? []
    const excludeIds = [card.id, ...carryOrigins.map((o) => o.id)]
    dragRef.current = { startX, startY, originX, originY, carryOrigins, excludeIds }
    setDragging(true)
    e.target.setPointerCapture(e.pointerId)
  }

  function handlePointerMove(e) {
    if (!dragRef.current) return
    const { startX, startY, originX, originY, carryOrigins, excludeIds } = dragRef.current
    // Screen-space pointer movement maps to a smaller world-space movement
    // as the canvas zooms in, and a larger one as it zooms out.
    const dx = (e.clientX - startX) / zoom
    const dy = (e.clientY - startY) / zoom
    const rawX = originX + dx
    const rawY = originY + dy
    const snappedX = snapToGrid(rawX)

    // Vertical position doesn't follow the dot grid: cards vary in height,
    // so instead we look for a neighboring card sharing this column and, if
    // one is within Y_SNAP_THRESHOLD, snap to a fixed gutter from its edge.
    let finalY = snapToGrid(rawY)
    let bestDist = Infinity
    const selfHeight = cardElRef.current?.offsetHeight ?? 0
    const siblings = getSiblingRects?.(excludeIds) ?? []

    for (const s of siblings) {
      const overlapsColumn = snappedX < s.x + s.width && snappedX + card.w > s.x
      if (!overlapsColumn) continue

      const gapBelow = rawY - (s.y + s.height)
      if (Math.abs(gapBelow) < Y_SNAP_THRESHOLD) {
        const candidate = s.y + s.height + Y_SNAP_GUTTER
        const dist = Math.abs(rawY - candidate)
        if (dist < bestDist) {
          bestDist = dist
          finalY = candidate
        }
      }

      const gapAbove = s.y - (rawY + selfHeight)
      if (Math.abs(gapAbove) < Y_SNAP_THRESHOLD) {
        const candidate = s.y - Y_SNAP_GUTTER - selfHeight
        const dist = Math.abs(rawY - candidate)
        if (dist < bestDist) {
          bestDist = dist
          finalY = candidate
        }
      }
    }

    // Never let the card end up straddling a group's top-edge no-fly zone —
    // it can still be placed inside the group or entirely above the border.
    finalY = clampYForGroupExclusions(snappedX, card.w, selfHeight, finalY, getGroupExclusions?.() ?? [])

    onMove(card.id, snappedX, finalY)

    // Carry the rest of the selection along by the same delta, keeping
    // their positions relative to this (snapped) card unchanged.
    const deltaX = snappedX - originX
    const deltaY = finalY - originY
    for (const o of carryOrigins) {
      onMove(o.id, o.x + deltaX, o.y + deltaY)
    }
  }

  function handlePointerUp(e) {
    dragRef.current = null
    setDragging(false)
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  // Big-text resize handles — same border-drag model as a group's, but
  // always available (not gated on selection) and reusing onUpdate.
  function handleResizeHandlePointerDown(dir, e) {
    e.stopPropagation()
    if (e.button !== 0) return
    resizeRef.current = {
      dir,
      startX: e.clientX,
      startY: e.clientY,
      origin: { x: card.x, y: card.y, w: card.w, h: card.h },
    }
    e.target.setPointerCapture(e.pointerId)
  }

  function handleResizeHandlePointerMove(e) {
    const state = resizeRef.current
    if (!state) return
    const { dir, startX, startY, origin } = state
    const dx = (e.clientX - startX) / zoom
    const dy = (e.clientY - startY) / zoom

    let { x, y, w, h } = origin

    if (dir.includes('e')) w = origin.w + dx
    if (dir.includes('s')) h = origin.h + dy
    if (dir.includes('w')) {
      w = origin.w - dx
      if (w < BIG_TEXT_MIN_W) {
        x = origin.x + origin.w - BIG_TEXT_MIN_W
        w = BIG_TEXT_MIN_W
      } else {
        x = origin.x + dx
      }
    }
    if (dir.includes('n')) {
      h = origin.h - dy
      if (h < BIG_TEXT_MIN_H) {
        y = origin.y + origin.h - BIG_TEXT_MIN_H
        h = BIG_TEXT_MIN_H
      } else {
        y = origin.y + dy
      }
    }

    w = Math.max(BIG_TEXT_MIN_W, w)
    h = Math.max(BIG_TEXT_MIN_H, h)

    onUpdate(card.id, {
      x: snapToGrid(x),
      y: snapToGrid(y),
      w: snapSize(w, BIG_TEXT_MIN_W),
      h: snapSize(h, BIG_TEXT_MIN_H),
    })
  }

  function handleResizeHandlePointerUp(e) {
    resizeRef.current = null
    try {
      e.target.releasePointerCapture(e.pointerId)
    } catch {
      // ignore
    }
  }

  return (
    <div
      ref={setCardEl}
      data-node-id={card.id}
      className={`card${isBig ? ' card--big' : ''}${isImage ? ' card--image' : ''}${dragging ? ' card--dragging' : ''}${selected ? ' card--selected' : ''}${connectTarget ? ' card--connect-target' : ''}`}
      style={{
        left: card.x,
        top: card.y,
        width: card.w,
        height: isBig ? card.h : undefined,
        borderColor: resolveColor(card.color, theme),
      }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
    >
      <div className="card__inner">
        <div className="card__bar" />

        {isImage && imageSrc && (
          // Full node width, height derived from the image's own intrinsic
          // aspect ratio (no explicit height is ever set) — always, since
          // nothing here constrains height directly.
          <img className="card__image" src={imageSrc} alt="" draggable={false} />
        )}

        <textarea
          ref={contentRef}
          className="card__content no-drag"
          value={card.content}
          placeholder="Write something..."
          onChange={(e) => onUpdate(card.id, { content: e.target.value })}
          rows={1}
        />
      </div>

      {/* Big text only — resizable in any direction like a group's border,
          always available (not gated on selection). */}
      {isBig &&
        HANDLES.map((dir) => (
          <div
            key={dir}
            className={`resize-handle resize-handle--${dir}`}
            onPointerDown={(e) => handleResizeHandlePointerDown(dir, e)}
            onPointerMove={handleResizeHandlePointerMove}
            onPointerUp={handleResizeHandlePointerUp}
          />
        ))}

      {(hovered || selected || connectTarget) &&
        SIDES.map((side) => (
          <div
            key={side}
            className={`node-connector node-connector--${side}${connectHoverSide === side ? ' node-connector--active' : ''}`}
            data-node-id={card.id}
            data-side={side}
          />
        ))}
    </div>
  )
}

import { useCallback, useEffect, useReducer, useRef } from 'react'
import {
  seedBoard,
  newCard,
  newGroup,
  newEdge,
  nextId,
  snapToGrid,
  GRID_SIZE,
  CARD_WIDTH,
  NEW_CARD_HEIGHT_ESTIMATE,
  DEFAULT_TEXT_SIZE,
} from '../data/board.js'

function boxesOverlap(a, b) {
  return a.left < b.left + b.width && a.left + a.width > b.left && a.top < b.top + b.height && a.top + a.height > b.top
}

// Drops any entry in `images` that no card actually references anymore —
// called after anything that could leave one behind (a card deleted, or
// re-converted to point at a different image), so the map doesn't
// accumulate stale base64 blobs forever.
function pruneOrphanedImages(cards, images) {
  const used = new Set(cards.filter((c) => c.imageId).map((c) => c.imageId))
  const kept = Object.fromEntries(Object.entries(images).filter(([id]) => used.has(id)))
  return Object.keys(kept).length === Object.keys(images).length ? images : kept
}

const STORAGE_KEY = 'kanvy.board'
const MAX_HISTORY = 100

// Rapid-fire updates within this window (e.g. every pointermove of a single
// drag) get folded into the same undo step, so undoing a drag jumps back to
// where it started rather than one pixel at a time. A genuine pause longer
// than this starts a fresh step.
const COALESCE_MS = 400

function loadInitialBoard() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw)
      // Explicit field-by-field reconstruction rather than a spread merge —
      // boards saved before grouping boxes/connections/images existed won't
      // have some of these, and however they were ordered in the *saved*
      // JSON, `images` must land last here so its (large, diff-unfriendly)
      // base64 blobs always serialize after the actual node data.
      return {
        groups: parsed.groups ?? [],
        edges: parsed.edges ?? [],
        cards: parsed.cards ?? [],
        images: parsed.images ?? {},
      }
    }
  } catch {
    // ignore corrupt storage, fall back to seed
  }
  return seedBoard
}

function historyReducer(state, action) {
  switch (action.type) {
    case 'update': {
      const next = action.updater(state.present)
      if (next === state.present) return state
      const now = Date.now()
      const coalesce = now - state.lastActionAt < COALESCE_MS
      const past = coalesce ? state.past : [...state.past, state.present].slice(-MAX_HISTORY)
      return { past, present: next, future: [], lastActionAt: now }
    }
    case 'undo': {
      if (state.past.length === 0) return state
      const present = state.past[state.past.length - 1]
      return {
        past: state.past.slice(0, -1),
        present,
        future: [state.present, ...state.future],
        lastActionAt: 0,
      }
    }
    case 'redo': {
      if (state.future.length === 0) return state
      const present = state.future[0]
      return {
        past: [...state.past, state.present],
        present,
        future: state.future.slice(1),
        lastActionAt: 0,
      }
    }
    default:
      return state
  }
}

export function useBoard() {
  const [state, dispatch] = useReducer(historyReducer, undefined, () => ({
    past: [],
    present: loadInitialBoard(),
    future: [],
    lastActionAt: 0,
  }))
  const board = state.present

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(board))
  }, [board])

  const update = useCallback((updater) => dispatch({ type: 'update', updater }), [])

  const addCard = useCallback(
    (opts) => {
      const card = newCard(opts)
      update((b) => ({ ...b, cards: [...b.cards, card] }))
      return card.id
    },
    [update],
  )

  // Images live in their own top-level map, keyed by id — a card only ever
  // holds a reference (`imageId`), never the data URI itself. See the
  // seedBoard comment in board.js for why.
  const addImageCard = useCallback(
    ({ x, y, dataUri, content }) => {
      const imageId = nextId('img')
      const card = newCard({ x, y, content, textSize: DEFAULT_TEXT_SIZE, imageId })
      update((b) => ({ ...b, cards: [...b.cards, card], images: { ...b.images, [imageId]: dataUri } }))
      return card.id
    },
    [update],
  )

  // Turns an existing card into an image card in place, keeping its text
  // and color — used when an image is pasted while that card is focused or
  // is the sole selection. Also normalizes it to a standard note's shape
  // (fixed width, auto height, regular-size text): an image card is never
  // "big text" sized, even if the card being converted was.
  const convertCardToImage = useCallback(
    (id, dataUri) => {
      const imageId = nextId('img')
      update((b) => {
        const cards = b.cards.map((c) =>
          c.id === id ? { ...c, imageId, textSize: DEFAULT_TEXT_SIZE, w: CARD_WIDTH, h: undefined } : c,
        )
        // The new image goes in before pruning, in case this card already
        // had a different one — that old entry is what pruning should drop.
        const images = pruneOrphanedImages(cards, { ...b.images, [imageId]: dataUri })
        return { ...b, cards, images }
      })
    },
    [update],
  )

  const addGroup = useCallback(
    (opts) => {
      const group = newGroup(opts)
      update((b) => ({ ...b, groups: [...b.groups, group] }))
      return group.id
    },
    [update],
  )

  const duplicateCards = useCallback(
    (ids) => {
      const idSet = new Set(ids)
      const originals = board.cards.filter((c) => idSet.has(c.id))
      if (originals.length === 0) return []
      const duplicates = originals.map((original) => ({
        ...original,
        id: nextId('c'),
        x: snapToGrid(original.x + GRID_SIZE * 2),
        y: snapToGrid(original.y + GRID_SIZE * 2),
      }))
      update((b) => ({ ...b, cards: [...b.cards, ...duplicates] }))
      return duplicates.map((d) => d.id)
    },
    [board, update],
  )

  const updateCard = useCallback(
    (id, patch) => {
      update((b) => ({
        ...b,
        cards: b.cards.map((c) => (c.id === id ? { ...c, ...patch } : c)),
      }))
    },
    [update],
  )

  const moveCard = useCallback(
    (id, x, y) => {
      update((b) => ({
        ...b,
        cards: b.cards.map((c) => (c.id === id ? { ...c, x, y } : c)),
      }))
    },
    [update],
  )

  const updateGroup = useCallback(
    (id, patch) => {
      update((b) => ({
        ...b,
        groups: b.groups.map((g) => (g.id === id ? { ...g, ...patch } : g)),
      }))
    },
    [update],
  )

  // At most one connection between any given pair of nodes, regardless of
  // which end a new drag starts from — dragging onto an already-connected
  // node just selects that existing connection instead of duplicating it.
  const addEdge = useCallback(
    (fromId, fromSide, toId, toSide) => {
      const existing = board.edges.find(
        (ed) => (ed.fromId === fromId && ed.toId === toId) || (ed.fromId === toId && ed.toId === fromId),
      )
      if (existing) return existing.id
      const edge = newEdge({ fromId, fromSide, toId, toSide })
      update((b) => ({ ...b, edges: [...b.edges, edge] }))
      return edge.id
    },
    [board, update],
  )

  const updateEdge = useCallback(
    (id, patch) => {
      update((b) => ({
        ...b,
        edges: b.edges.map((ed) => (ed.id === id ? { ...ed, ...patch } : ed)),
      }))
    },
    [update],
  )

  // In-memory only — "primarily concerned about within the app" for now,
  // not system-clipboard/cross-window interop. Cards and groups only; edges
  // between copied nodes aren't carried over yet. Each paste from the same
  // copy offsets a bit further (a staircase, like repeated Cmd+D), tracked
  // via pasteCount rather than reading current positions, since paste — unlike
  // duplicate — doesn't operate on "whatever's currently selected".
  const clipboardRef = useRef(null)

  const copySelection = useCallback(
    (ids) => {
      const idSet = new Set(ids)
      const cards = board.cards.filter((c) => idSet.has(c.id)).map((c) => ({ ...c }))
      const groups = board.groups.filter((g) => idSet.has(g.id)).map((g) => ({ ...g }))
      if (cards.length === 0 && groups.length === 0) return false
      clipboardRef.current = { cards, groups, pasteCount: 0 }
      return true
    },
    [board],
  )

  const pasteClipboard = useCallback(() => {
    const clip = clipboardRef.current
    if (!clip || (clip.cards.length === 0 && clip.groups.length === 0)) return []
    clip.pasteCount += 1

    // Bounding box of everything being pasted, at its original (pre-offset)
    // position — a card's real height isn't known without rendering it, so
    // this uses the same rough estimate creation/no-fly-zone placement does.
    let left = Infinity
    let top = Infinity
    let right = -Infinity
    let bottom = -Infinity
    for (const c of clip.cards) {
      left = Math.min(left, c.x)
      top = Math.min(top, c.y)
      right = Math.max(right, c.x + (c.w ?? CARD_WIDTH))
      bottom = Math.max(bottom, c.y + (c.textSize === 'big' ? c.h : NEW_CARD_HEIGHT_ESTIMATE))
    }
    for (const g of clip.groups) {
      left = Math.min(left, g.x)
      top = Math.min(top, g.y)
      right = Math.max(right, g.x + g.w)
      bottom = Math.max(bottom, g.y + g.h)
    }
    const clipBox = { left, top, width: right - left, height: bottom - top }

    // A small staircase offset by default (matching repeated Cmd+D), but if
    // that would land the paste overlapping ANY existing group — including
    // the one it was just copied from — it's pushed further out along the
    // same diagonal until it's clear of all of them. Pasted content always
    // lands on the raw canvas, never spatially "inside" a group by default,
    // since group membership is purely spatial with no formal ownership —
    // landing inside one would make it look adopted by that group.
    const staircase = GRID_SIZE * 2 * clip.pasteCount
    const step = GRID_SIZE * 4
    let offset = staircase
    for (let attempt = 0; attempt < 40; attempt++) {
      const candidate = { left: clipBox.left + offset, top: clipBox.top + offset, width: clipBox.width, height: clipBox.height }
      const overlapsAnyGroup = board.groups.some((g) =>
        boxesOverlap(candidate, { left: g.x, top: g.y, width: g.w, height: g.h }),
      )
      if (!overlapsAnyGroup) break
      offset += step
    }

    const newCards = clip.cards.map((c) => ({
      ...c,
      id: nextId('c'),
      x: snapToGrid(c.x + offset),
      y: snapToGrid(c.y + offset),
    }))
    const newGroups = clip.groups.map((g) => ({
      ...g,
      id: nextId('g'),
      x: snapToGrid(g.x + offset),
      y: snapToGrid(g.y + offset),
    }))
    update((b) => ({ ...b, cards: [...b.cards, ...newCards], groups: [...b.groups, ...newGroups] }))
    return [...newCards.map((c) => c.id), ...newGroups.map((g) => g.id)]
  }, [board, update])

  const removeItems = useCallback(
    (ids) => {
      const idSet = new Set(ids)
      update((b) => {
        const cards = b.cards.filter((c) => !idSet.has(c.id))
        return {
          ...b,
          cards,
          groups: b.groups.filter((g) => !idSet.has(g.id)),
          // Also drops any edge attached to a card/group that got deleted,
          // not just edges the user selected directly.
          edges: b.edges.filter((ed) => !idSet.has(ed.id) && !idSet.has(ed.fromId) && !idSet.has(ed.toId)),
          images: pruneOrphanedImages(cards, b.images),
        }
      })
    },
    [update],
  )

  const undo = useCallback(() => dispatch({ type: 'undo' }), [])
  const redo = useCallback(() => dispatch({ type: 'redo' }), [])

  return {
    board,
    addCard,
    addImageCard,
    convertCardToImage,
    addGroup,
    addEdge,
    duplicateCards,
    copySelection,
    pasteClipboard,
    updateCard,
    moveCard,
    updateGroup,
    updateEdge,
    removeItems,
    undo,
    redo,
    canUndo: state.past.length > 0,
    canRedo: state.future.length > 0,
  }
}

import { DEFAULT_PATTERN } from './patterns.js'

// Tag/card colors — Nord's Frost + Aurora accents (nord3, nord7-9, nord11-15).
// Nord has no pink, so that slot borrows nord9 (a mid blue) instead.
export const COLORS = {
  gray: '#4c566a', // nord3
  coral: '#bf616a', // nord11
  amber: '#ebcb8b', // nord13
  lime: '#a3be8c', // nord14
  teal: '#8fbcbb', // nord7
  sky: '#88c0d0', // nord8
  violet: '#b48ead', // nord15
  pink: '#81a1c1', // nord9
}

// nord3 (COLORS.gray) is a muted, low-contrast neutral against Polar
// Night's dark surfaces, but reads as a strong, standout mid-dark tone
// against Snow Storm's light ones — the opposite of "subtle" there. This is
// what "gray" actually resolves to in light mode instead, matching the same
// quiet, low-contrast quality relative to its (light) surroundings.
export const GRAY_LIGHT = '#b8c0cc'

// The default color — assigned to freshly created cards/groups/edges, and
// the first swatch in every color picker — is the one place where "gray"
// needs to actually look neutral in both themes, not just in dark mode.
// Everything else in COLORS reads reasonably against either theme as-is.
export function resolveColor(colorKey, theme) {
  if (colorKey === 'gray' && theme === 'light') return GRAY_LIGHT
  return COLORS[colorKey] ?? COLORS.gray
}

// What a color picker swatch button should show — a plain fill for every
// static color, but a half-light/half-dark split for "gray" specifically,
// so its swatch visibly signals "this one changes with the theme" rather
// than looking like just another fixed color. Always shows both halves
// regardless of the current theme — resolveColor (above) is what picks the
// single theme-appropriate one for actually rendering a card/group/edge.
export function swatchBackground(colorKey) {
  if (colorKey === 'gray') return `linear-gradient(90deg, ${GRAY_LIGHT} 50%, ${COLORS.gray} 50%)`
  return COLORS[colorKey] ?? COLORS.gray
}

// Neutral default for freshly created cards; duplicates keep their source's color.
export const DEFAULT_COLOR = 'gray'

// Matches the dot-matrix background pitch in index.css. Cards snap to the
// midpoints between dots (offset by half a cell) rather than onto the dots
// themselves, so corners land in the gaps of the dot matrix.
export const GRID_SIZE = 16
const GRID_OFFSET = GRID_SIZE / 2

export function snapToGrid(value) {
  return Math.round((value - GRID_OFFSET) / GRID_SIZE) * GRID_SIZE + GRID_OFFSET
}

// All cards share one fixed width, a multiple of GRID_SIZE, so the left and
// right edges both land on grid midpoints. Kept close to its prior 220px
// value even though GRID_SIZE shrank.
export const CARD_WIDTH = GRID_SIZE * 14

// A regular card's height grows with content, so it's not in the data model
// at all — this is only a rough stand-in for placement heuristics (keeping
// a freshly created or pasted card clear of a group's no-fly zone, or clear
// of groups entirely on paste) that need *some* height before anything has
// ever been rendered to measure.
export const NEW_CARD_HEIGHT_ESTIMATE = 90

// Text size is a per-card attribute, not a separate node type. 'regular' is
// the normal note: fixed width, height grows with content. 'big' is a
// freeform box — resizable in any direction like a group, with a large
// font, that truncates instead of scrolling when content overflows it.
export const DEFAULT_TEXT_SIZE = 'regular'
export const BIG_TEXT_MIN_W = GRID_SIZE * 10
export const BIG_TEXT_MIN_H = GRID_SIZE * 6
export const BIG_TEXT_DEFAULT_W = GRID_SIZE * 16
export const BIG_TEXT_DEFAULT_H = GRID_SIZE * 8

// Grouping boxes: freeform rectangles cards can be arranged over. Always
// rendered beneath cards (see Board.jsx render order) and, unlike cards,
// resized directly by dragging their border.
export const GROUP_MIN_W = GRID_SIZE * 8
export const GROUP_MIN_H = GRID_SIZE * 6
export const DEFAULT_GROUP_COLOR = 'sky'

// Cards have varying heights (text, later images), so vertical position
// doesn't snap to the dot grid the way horizontal position does. Instead,
// when a drop lands within two grid cells of a neighboring card's edge,
// it snaps to a fixed gutter from that edge, keeping vertical spacing
// visually consistent regardless of content height.
export const Y_SNAP_THRESHOLD = GRID_SIZE * 2
export const Y_SNAP_GUTTER = GRID_SIZE

let uid = 0
export function nextId(prefix) {
  uid += 1
  return `${prefix}${Date.now().toString(36)}${uid}`
}

// Connections between two nodes (cards or groups). Direction picks which
// end (if either) gets an arrowhead: 'forward' points toId-ward, 'backward'
// points fromId-ward, 'none' is a plain line. fromSide/toSide are which of
// the node's 4 sides the connection attaches to — chosen once by the user
// when drawing it and fixed from then on (Board.jsx never recomputes them),
// so the line can deliberately bend around rather than always taking the
// shortest path.
export const DEFAULT_EDGE_DIRECTION = 'none'
// Same palette as cards/groups, so edges get the same color picker.
export const DEFAULT_EDGE_COLOR = 'gray'

// The whole app state is this one JSON structure. Used only when localStorage
// has no saved board yet (see useBoard.js) — a single starter note, not a
// demo/tour board, since there's no "reset" affordance to get back to a
// clean slate anymore.
//
// `images` is deliberately the *last* key, and every board-mutating action
// in useBoard.js is written to preserve that ordering: a card with a
// picture references it by `imageId` rather than embedding the data URI
// inline, and the actual (large, unreadable-as-a-diff) base64 blobs all
// live together in `images`, keyed by that id. That keeps the "nodes"
// section of the JSON — the part worth actually reading in a diff — free of
// giant base64 strings, with all of that noise pushed to the end instead.
export const seedBoard = {
  groups: [],
  edges: [],
  cards: [
    {
      id: 'c1',
      x: snapToGrid(80),
      y: snapToGrid(100),
      w: CARD_WIDTH,
      color: 'amber',
      content: 'Welcome to Kanvy\n\nDouble-click the canvas to add a note.',
    },
  ],
  images: {},
}

export function newCard({
  x,
  y,
  color = DEFAULT_COLOR,
  textSize = DEFAULT_TEXT_SIZE,
  content = '',
  imageId,
} = {}) {
  return {
    id: nextId('c'),
    x: snapToGrid(x ?? 120),
    y: snapToGrid(y ?? 120),
    w: CARD_WIDTH,
    color,
    textSize,
    content,
    imageId,
  }
}

export function newGroup({ x, y, w, h, color = DEFAULT_GROUP_COLOR, pattern = DEFAULT_PATTERN } = {}) {
  return {
    id: nextId('g'),
    x: snapToGrid(x ?? 120),
    y: snapToGrid(y ?? 120),
    w: Math.max(GROUP_MIN_W, w ?? GROUP_MIN_W),
    h: Math.max(GROUP_MIN_H, h ?? GROUP_MIN_H),
    color,
    pattern,
  }
}

export function newEdge({
  fromId,
  fromSide,
  toId,
  toSide,
  direction = DEFAULT_EDGE_DIRECTION,
  color = DEFAULT_EDGE_COLOR,
} = {}) {
  return { id: nextId('e'), fromId, fromSide, toId, toSide, direction, color }
}

