/* Clipping lives here rather than on .card itself, so the connector dots
   (siblings of this, direct children of .card) can sit outside the border
   without being cut off. */
.card__inner {
  overflow: hidden;
  border-radius: var(--radius);
}

.card:hover {
  background: var(--surface-hover);
}

.card--selected {
  outline: 2px solid var(--outline);
  outline-offset: 2px;
  z-index: 5;
}

.card--dragging {
  cursor: grabbing;
  z-index: 10;
}

/* Shown on whichever node a connection drag is currently hovering, so it's
   obvious exactly where releasing will attach. */
.card--connect-target {
  outline: 3px solid #8fbcbb;
  outline-offset: 2px;
}

.card__bar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 16px; /* matches GRID_SIZE in board.js */
  padding: 1px 3px;
  background: var(--dot);
  border-bottom: 1px solid var(--border-soft);
}

.card__image {
  display: block;
  width: 100%;
  height: auto; /* intrinsic aspect ratio, always — never cropped/stretched */
  border-bottom: 1px solid var(--border-soft);
  cursor: grab;
}

.card__content {
  display: block;
  width: 100%;
  min-height: 64px;
  border: none;
  resize: none;
  overflow: hidden;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 8px;
  background: transparent;
  cursor: text;
}

.card__content:focus {
  outline: none;
}

/* Big text: an explicit height (set inline from card.h) instead of growing
   with content, a large font, and — since it never scrolls internally —
   overflow is just clipped (truncated) rather than given a scrollbar.
   The content area is absolutely positioned to exactly fill the space below
   the bar (17px = card__bar's 16px min-height + 1px border) rather than
   relying on flexbox to shrink it: a <textarea>'s intrinsic content size
   otherwise wins over flex-shrink in most browsers even with min-height: 0,
   which was silently defeating the truncation. */
.card--big .card__inner {
  position: relative;
  height: 100%;
}

.card--big .card__content {
  position: absolute;
  inset: 17px 0 0 0;
  height: auto;
  overflow: hidden;
  font-size: 3rem;
  line-height: 1.2;
}

/* ---------- group ---------- */

/* Never given a z-index — its stacking relies entirely on DOM order (it's
   rendered before cards in Board.jsx) so notes always paint on top of it. */
.group {
  position: absolute;
  background-color: var(--surface);
  background-repeat: repeat;
  border: 3px solid var(--line);
  border-radius: var(--radius);
  user-select: none;
}

