:root {
  color-scheme: light;
  /* Nord palette: Snow Storm (nord4-6) for light-mode surfaces, Polar
     Night nord0 for ink. */
  --paper: #e5e9f0; /* nord5 */
  --ink: #2e3440; /* nord0 */
  --line: #2e3440; /* nord0 */
  --surface: #eceff4; /* nord6 */
  --surface-hover: #d8dee9; /* nord4 */
  --dot: rgba(46, 52, 64, 0.08);
  --border-soft: rgba(46, 52, 64, 0.2);
  --outline: rgba(46, 52, 64, 0.45);
  /* Opaque equivalent of --border-soft — needed anywhere a translucent
     border would otherwise blend with (and visibly reveal) whatever's
     painted underneath it, like a swatch's own split-color fill. */
  --border-static: #c7cbd2;
  --radius: 5px;
  font-family: 'Fira Code', 'Courier New', monospace;
}

[data-theme='dark'] {
  color-scheme: dark;
  /* Polar Night (nord0-3) for dark-mode surfaces, Snow Storm nord6 for ink. */
  --paper: #2e3440; /* nord0 */
  --ink: #eceff4; /* nord6 */
