/* No pointer-events on the SVG root — its transparent area must let clicks
   through to the marquee/pan handling below it. Each edge's own hit-path
   re-enables pointer-events just along its stroke. */
.board__edges {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none;
}

.edge__hit {
  fill: none;
  stroke: transparent;
  stroke-width: 14;
  pointer-events: stroke;
  cursor: pointer;
}

/* A wider, neutral-surface stroke under the colored line so it stays
   readable over a busy group pattern instead of blending into it. */
.edge__halo {
  fill: none;
  stroke: var(--surface);
  stroke-width: 6;
  stroke-linecap: round;
  pointer-events: none;
}

.edge__line {
  fill: none;
  stroke: var(--edge-color, #4c566a);
  stroke-width: 3;
  stroke-linecap: round;
  pointer-events: none;
}

.edge--selected .edge__halo {
  stroke-width: 7;
}

.edge--selected .edge__line {
  /* Opaque, unlike var(--outline) (an rgba() meant for border-style
     decoration) — using that here let the background show through a
     filled shape like the arrowhead, reading as an odd transparency. */
  stroke: var(--ink);
  stroke-width: 4;
}

.edge__arrowhead--selected {
  fill: var(--ink);
}

.board__edge-preview {
  fill: none;
  stroke: #4c566a;
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 6 4;
}

.edge-menu__btn {
  width: 20px;
  height: 20px;
  border-radius: 4px;
  border: 2px solid var(--border-soft);
  background: var(--surface);
  color: var(--ink);
  font-size: 0.85rem;
  line-height: 1;
  padding: 0;

