  coral: '#bf616a', // nord11
  amber: '#ebcb8b', // nord13
  lime: '#a3be8c', // nord14
  teal: '#8fbcbb', // nord7
  sky: '#88c0d0', // nord8
  violet: '#b48ead', // nord15
  pink: '#81a1c1', // nord9
}

