    case 'blocked':
      return '#bf616a' // nord11
    case 'in_progress':
      return '#5e81ac' // nord10
    case 'done':
      return '#a3be8c' // nord14
    default:
      return theme === 'light' ? '#4c566a' /* nord3 */ : '#d8dee9' /* nord4 */
