import { useEffect, useRef, useState } from 'react'
import { Download, Sun, Moon, Eye, List, ListTodo, ListClock } from 'lucide-react'

const VIEW_MODES = [
  { key: 'standard', label: 'Standard', Icon: List },
  { key: 'task', label: 'Task', Icon: ListTodo },
  // Not implemented yet — selectable now so the option exists, but it
  // currently renders identically to standard mode.
  { key: 'recency', label: 'Recency', Icon: ListClock },
]

export default function Toolbar({ onDownload, theme, onToggleTheme, viewMode, onViewModeChange }) {
  const [menuOpen, setMenuOpen] = useState(false)
  const wrapRef = useRef(null)

  useEffect(() => {
    if (!menuOpen) return
    function onPointerDown(e) {
      if (!wrapRef.current?.contains(e.target)) setMenuOpen(false)
    }
    window.addEventListener('pointerdown', onPointerDown)
    return () => window.removeEventListener('pointerdown', onPointerDown)
  }, [menuOpen])

  return (
    <div className="toolbar">
      <span className="toolbar__brand">kanvy</span>

      <button
        className="toolbar__btn toolbar__btn--icon toolbar__btn--ghost"
        onClick={onToggleTheme}
        title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
      >
        {theme === 'dark' ? <Sun size={16} strokeWidth={2} /> : <Moon size={16} strokeWidth={2} />}
      </button>

      <div className="toolbar__view-menu-wrap" ref={wrapRef}>
        <button
          className="toolbar__btn toolbar__btn--icon"
          onClick={() => setMenuOpen((open) => !open)}
          title="Change view mode"
        >
          <Eye size={16} strokeWidth={2} />
        </button>

        {menuOpen && (
          <div className="toolbar__view-menu">
            {VIEW_MODES.map(({ key, label, Icon }) => (
              <button
                key={key}
                className={`toolbar__view-menu-item${viewMode === key ? ' toolbar__view-menu-item--active' : ''}`}
                onClick={() => {
                  onViewModeChange(key)
                  setMenuOpen(false)
                }}
              >
                <Icon size={14} strokeWidth={2} />
                {label}
              </button>
            ))}
          </div>
        )}
      </div>

      <button
        className="toolbar__btn toolbar__btn--icon"
        onClick={onDownload}
        title="Download the board as a JSON file"
      >
        <Download size={16} strokeWidth={2} />
      </button>
    </div>
  )
}

