  groups: [],
  edges: [],
  cards: [
    {
      id: 'c1',
      x: snapToGrid(80),
      y: snapToGrid(100),
      w: CARD_WIDTH,
      color: 'amber',
      content: 'Welcome to Kanvy\n\nDouble-click the canvas to add a note.',
      createdAt: nowISO(),
      updatedAt: nowISO(),
    },
  ],
  images: {},
}

export function newCard({
  x,
  y,
  color = DEFAULT_COLOR,
  textSize = DEFAULT_TEXT_SIZE,
  content = '',
  imageId,
  linkUrl,
  linkTitle,
  linkImageUrl,
  linkStatus,
} = {}) {
  return {
    id: nextId('c'),
    x: snapToGrid(x ?? 120),
    y: snapToGrid(y ?? 120),
    w: CARD_WIDTH,
    color,
    textSize,
    content,
    imageId,
