// south and east edges). Corners combine two single-edge adjustments.
const HANDLES = ['n', 's', 'e', 'w', 'ne', 'nw', 'se', 'sw']

function snapSize(value, min) {
  return Math.max(min, Math.round(value / GRID_SIZE) * GRID_SIZE)
}

