// Paste into the browser devtools console on the Kanvy page, then it reloads automatically.
// Randomly spreads updatedAt across all four recency buckets so you can see
// green/yellow/orange/red at a glance in viz > recency.
(function () {
  const KEY = 'kanvy.board'
  const raw = localStorage.getItem(KEY)
  if (!raw) {
    console.error('No kanvy.board found in localStorage.')
    return
  }
  const board = JSON.parse(raw)

  // Upper bound (ms ago) for each bucket, matching RECENCY_THRESHOLDS_MS in
  // board.js — picks a random age just inside each bucket so all four show.
  const BUCKETS_MS = [
    60 * 1000, // a minute ago -> green
    3 * 24 * 60 * 60 * 1000, // ~3 days ago -> yellow
    20 * 24 * 60 * 60 * 1000, // ~20 days ago -> orange
    90 * 24 * 60 * 60 * 1000, // ~90 days ago -> red
  ]

  function randomPastIso() {
    const maxAge = BUCKETS_MS[Math.floor(Math.random() * BUCKETS_MS.length)]
    const age = Math.random() * maxAge
    return new Date(Date.now() - age).toISOString()
  }

  let count = 0
  for (const entity of [...(board.cards ?? []), ...(board.groups ?? [])]) {
    entity.updatedAt = randomPastIso()
    count++
  }

  localStorage.setItem(KEY, JSON.stringify(board))
  console.log(`Randomized updatedAt on ${count} card(s)/group(s). Reloading...`)
  location.reload()
})()

