    60 * 1000,                    // a minute ago -> green
    3 * 24 * 60 * 60 * 1000,      // ~3 days ago  -> yellow
    20 * 24 * 60 * 60 * 1000,     // ~20 days ago -> orange
    90 * 24 * 60 * 60 * 1000,     // ~90 days ago -> red
  ]

  function randomPastIso() {
    const maxAge = BUCKETS_MS[Math.floor(Math.random() * BUCKETS_MS.length)]
    const age = Math.random() * maxAge
    return new Date(Date.now() - age).toISOString()
  }

  let count = 0
  for (const entity of [...(board.cards ?? []), ...(board.groups ?? [])]) {
    entity.updatedAt = randomPastIso()
    count++
  }

  localStorage.setItem(KEY, JSON.stringify(board))
  console.log(`Randomized updatedAt on ${count} card(s)/group(s). Reloading...`)
  location.reload()
})()
```

Open devtools console on the Kanvy tab, paste that in, hit enter — it'll randomly bucket every card/group's `updatedAt` across the four recency tiers and reload so you can flip to viz > recency and see all four colors. Re-run it anytime for a fresh shuffle.

