import { Sun, Moon, Eye, List, ListTodo, ListClock, FileJson, Image } from 'lucide-react'
import ToolbarMenu from './ToolbarMenu.jsx'

const VIEW_MODES = [
  { key: 'standard', label: 'Standard', icon: List },
  { key: 'task', label: 'Task', icon: ListTodo },
  { key: 'recency', label: 'Recency', icon: ListClock },
]

export default function Toolbar({ onDownloadJson, onDownloadImage, theme, onToggleTheme, viewMode, onViewModeChange }) {
  const downloadItems = [
    { key: 'json', label: 'Download as JSON', icon: FileJson, onClick: onDownloadJson },
    { key: 'image', label: 'Download as image', icon: Image, onClick: onDownloadImage },
  ]

  return (
    <div className="toolbar">
      <span className="toolbar__brand">kanvy</span>

      {/* Anchors the right-aligned cluster of buttons (margin-left: auto is
          on this wrapper, not the button) — it goes first in that cluster
          so its dropdown, which grows rightward from here, has the other
          buttons' width as breathing room instead of immediately hitting
          the edge of the window. */}
      <ToolbarMenu icon={Eye} title="Change view mode" align="left" items={VIEW_MODES.map((m) => ({ ...m, active: viewMode === m.key, onClick: () => onViewModeChange(m.key) }))} />

      <button
        className="toolbar__btn toolbar__btn--icon"
        onClick={onToggleTheme}
        title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
      >
        {theme === 'dark' ? <Sun size={16} strokeWidth={2} /> : <Moon size={16} strokeWidth={2} />}
      </button>

      {/* Rightmost button in the toolbar — its dropdown aligns to the right
          edge (growing leftward) instead of the left, for the same reason
          the viz menu above got reordered rather than left as the last
          button: 'left' alignment here would run the menu off the window. */}
      <ToolbarMenu icon={FileJson} title="Download the board" align="right" items={downloadItems} />
    </div>
  )
}

