import { useEffect, useRef, useState } from 'react'

// Shared dropdown-from-a-toolbar-icon pattern (viz mode, download) — same
// open/close/click-outside behavior and the same look, so the two don't
// drift out of sync with each other over time.
//
// `align`: which edge of the trigger button the dropdown hangs from.
// 'left' grows rightward — fine for a button with room to its right, but
// for the rightmost button in the toolbar that runs the menu straight off
// the edge of the window (this is what happened to the viz menu before it
// was reordered). 'right' grows leftward instead, staying on-screen
// regardless of how close to the edge the trigger sits.
export default function ToolbarMenu({ icon: Icon, title, align = 'left', items }) {
  const [open, setOpen] = useState(false)
  const wrapRef = useRef(null)

  useEffect(() => {
    if (!open) return
    function onPointerDown(e) {
      if (!wrapRef.current?.contains(e.target)) setOpen(false)
    }
    window.addEventListener('pointerdown', onPointerDown)
    return () => window.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  return (
    <div className="toolbar__menu-wrap" ref={wrapRef}>
      <button className="toolbar__btn toolbar__btn--icon" onClick={() => setOpen((o) => !o)} title={title}>
        <Icon size={16} strokeWidth={2} />
      </button>

      {open && (
        <div className={`toolbar__menu toolbar__menu--${align}`}>
          {items.map(({ key, label, icon: ItemIcon, active, onClick }) => (
            <button
              key={key}
              className={`toolbar__menu-item${active ? ' toolbar__menu-item--active' : ''}`}
              onClick={() => {
                onClick()
                setOpen(false)
              }}
            >
              <ItemIcon size={14} strokeWidth={2} />
              {label}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

