      ref={importInputRef}
      type="file"
      accept="application/json,.json"
      onChange={handleImportFileChange}
      style={{ display: 'none' }}
    />
    <Toolbar
      onDownload={handleDownload}
      onImport={handleImportClick}
      theme={theme}
      onToggleTheme={toggleTheme}
