  // The download menu's "Image" option — renders every card and group at
  // their real (1x, unpanned/unzoomed) size and position, cropped to
  // their combined extent rather than whatever's currently in the
  // viewport, so the exported image always shows the *whole* board.
  // Returns null (rather than letting the promise reject) on failure —
  // App.jsx surfaces that to the user instead of silently doing nothing.
  async exportImage() {
    const layerEl = boardLayerRef.current
    if (!layerEl) return null

    const PADDING = GRID_SIZE * 2

    // A card's real height only exists in the DOM (it grows with
    // content) — this reads the actual rendered size rather than the
    // rough estimate used for placement heuristics elsewhere.
    let left = Infinity
    let top = Infinity
    let right = -Infinity
    let bottom = -Infinity
    for (const card of board.cards) {
      const h = card.textSize === 'big' ? card.h : (cardElsRef.current.get(card.id)?.offsetHeight ?? NEW_CARD_HEIGHT_ESTIMATE)
      left = Math.min(left, card.x)
      top = Math.min(top, card.y)
      right = Math.max(right, card.x + card.w)
      bottom = Math.max(bottom, card.y + h)
    }
    for (const group of board.groups) {
      left = Math.min(left, group.x)
      top = Math.min(top, group.y)
      right = Math.max(right, group.x + group.w)
      bottom = Math.max(bottom, group.y + group.h)
    }
    if (!Number.isFinite(left)) {
      // Nothing on the board — a small blank canvas beats erroring.
      left = 0
      top = 0
      right = CARD_WIDTH
      bottom = NEW_CARD_HEIGHT_ESTIMATE
    }
    const width = right - left + PADDING * 2
    const height = bottom - top + PADDING * 2

    // A real, positioned clone — laid out by the browser exactly like
    // the original (same stylesheet, same classes) — rather than
    // fighting html-to-image's own width/height/style-override options
    // against .board__layer's `position: absolute; inset: 0`, which
    // sizes it to the *viewport*, not the actual extent of the content.
    const clone = layerEl.cloneNode(true)
    clone.style.position = 'absolute'
    clone.style.inset = '0'
    clone.style.transform = `translate(${PADDING - left}px, ${PADDING - top}px)`

    // A link card's preview image is fetched from a third party
    // (microlink.io — see linkMetadata.js) without our control over its
    // CORS headers. Drawing a cross-origin image onto a canvas without
    // permissive CORS taints it, aborting the *entire* export — so
    // rather than risk one link card's thumbnail breaking the whole
    // image, any <img> that isn't already an embedded data: URI (every
    // image *we* store is) is dropped from the export outright.
    clone.querySelectorAll('img').forEach((img) => {
      if (!img.src.startsWith('data:')) img.remove()
    })

    // SVG <marker> ids are global — cloning duplicates them onto the
    // clone while the original is still in the document, which can make
    // a url(#id) reference from either copy resolve ambiguously.
    // Rewritten here so the export is unambiguous and the live board is
    // never at risk of a flickered/wrong arrowhead.
    const idMap = new Map()
    clone.querySelectorAll('marker[id]').forEach((marker) => {
      const newId = `${marker.id}-export`
      idMap.set(marker.id, newId)
      marker.id = newId
    })
    clone.querySelectorAll('[marker-end], [marker-start]').forEach((el) => {
      for (const attr of ['marker-end', 'marker-start']) {
        const match = el.getAttribute(attr)?.match(/url\(#([^)]+)\)/)
        if (match && idMap.has(match[1])) el.setAttribute(attr, `url(#${idMap.get(match[1])})`)
      }
    })

    // Off-screen (not display:none/visibility:hidden — those skip
    // painting, which the capture depends on), so nothing flashes on
    // screen for the user during the brief moment this is in the DOM.
    const wrapper = document.createElement('div')
    wrapper.style.position = 'fixed'
    wrapper.style.top = '0'
    wrapper.style.left = '-99999px'
    wrapper.style.width = `${width}px`
    wrapper.style.height = `${height}px`
    wrapper.style.overflow = 'hidden'
    wrapper.style.background =
      getComputedStyle(document.documentElement).getPropertyValue('--paper').trim() || '#eceff4'
    // Same dot-grid look as the real canvas at 100% zoom.
    wrapper.style.backgroundImage = 'radial-gradient(var(--dot) 1px, transparent 1px)'
    wrapper.style.backgroundSize = `${GRID_SIZE}px ${GRID_SIZE}px`
    wrapper.appendChild(clone)
    document.body.appendChild(wrapper)

    try {
      // Layout needs to actually commit before html-to-image reads
      // computed styles off the freshly appended clone.
      await new Promise((resolve) => requestAnimationFrame(resolve))
      // skipFonts: embedding the Google Fonts webfont is slow and one
      // more thing that can fail (a blocked/slow network request) for a
      // cosmetic-only difference — the exported text just falls back to
      // the same monospace stack the page itself falls back to.
      return await toBlob(wrapper, { pixelRatio: 2, skipFonts: true })
    } catch (err) {
      console.error('Image export failed:', err)
      return null
    } finally {
      document.body.removeChild(wrapper)
    }
  },
}))

