      const worldCenterX = box.left + box.width / 2
      const worldCenterY = box.top + box.height / 2
      const anchorX = rect.width / 2
      const anchorY = rect.height / 2
      return { ...v, x: anchorX - worldCenterX * v.zoom, y: anchorY - worldCenterY * v.zoom }
