input.new_string:
.board {
  position: relative;
  flex: 1 1 auto;
  overflow: hidden;
  min-height: 0;
  background-image: radial-gradient(var(--dot) 1px, transparent 1px);
  /* Without this, a fast click-drag anywhere on the canvas (not just over
     a card) can pick up an incidental text selection instead of panning/
     marqueeing, which some browsers then let you "drag out" as a ghost
     snapshot of the whole board — the same way dragging a highlighted
     selection on any other page would. Doesn't affect typing/selecting
     inside a note's own textarea; form controls stay selectable/editable
     regardless of an ancestor's user-select. */
  user-select: none;
